-- NEET UG previous-year questions (official NTA papers), 2015.
-- Question text is the exam's; answers are solved and cross-checked independently by UG Prep
-- (not the official key); one-liners and explanations are original. Idempotent by id.
INSERT INTO public.questions (id, exam, subject, topic, stem, options, correct_option_id, one_liner,
  explanation, distractors, high_yield, difficulty, is_pyq, pyq_year, repeat_count, source, image_url)
VALUES
('00790343-429a-514f-a0b6-7e82c8c66213', 'neet_ug', 'Chemistry', 'The d- and f-Block Elements', 'Gadolinium belongs to 4f series. Its atomic number is 64. Which of the following is the correct electronic configuration of gadolinium?', '[{"id": "a", "text": "[Xe] 4f⁷5d¹6s²"}, {"id": "b", "text": "[Xe] 4f⁶5d²6s²"}, {"id": "c", "text": "[Xe] 4f⁸6d²"}, {"id": "d", "text": "[Xe] 4f⁹5s¹"}]'::jsonb, 'a', 'Gd (Z = 64) is [Xe]4f⁷5d¹6s², keeping a stable half-filled 4f subshell.', 'After Xe (54) there are 10 electrons: 6s² takes 2, leaving 8. Instead of 4f⁸, Gd puts 7 in 4f (half-filled, extra stable) and 1 in 5d.', '{"b": "4f⁶ breaks the half-filled stability for no gain.", "c": "6d is not occupied in a lanthanide, and 6s is missing.", "d": "5s is already filled in the Xe core; this electron count is wrong."}'::jsonb, 'Gd and Lu have a 5d¹ electron: Gd = [Xe]4f⁷5d¹6s², Lu = [Xe]4f¹⁴5d¹6s².', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('3727f68d-7465-5b3c-9244-bc2e526f3feb', 'neet_ug', 'Chemistry', 'Classification of Elements and Periodicity in Properties', 'The formation of the oxide ion, O²⁻(g), from oxygen atom requires first an exothermic and then an endothermic step as shown below:
O(g) + e⁻ → O⁻(g); ΔH° = –141 kJ mol⁻¹
O⁻(g) + e⁻ → O²⁻(g); ΔH° = +780 kJ mol⁻¹
Thus process of formation of O²⁻ in gas phase is unfavourable even though O²⁻ is isoelectronic with neon. It is due to the fact that,', '[{"id": "a", "text": "Oxygen is more electronegative"}, {"id": "b", "text": "Addition of electron in oxygen results in larger size of the ion"}, {"id": "c", "text": "Electron repulsion outweighs the stability gained by achieving noble gas configuration"}, {"id": "d", "text": "O⁻ ion has comparatively smaller size than oxygen atom"}]'::jsonb, 'c', 'Adding an electron to the already negative O⁻ meets strong repulsion that outweighs the gain from a neon-like configuration.', 'The second electron gain is endothermic (+780 kJ mol⁻¹) because the incoming electron is repelled by the negative charge of the small O⁻ ion. This repulsion costs more energy than is gained by reaching the noble-gas configuration, so O²⁻(g) is unfavourable.', '{"a": "Electronegativity does not explain why the second step is endothermic.", "b": "The size increase is a result, not the energetic reason.", "d": "O⁻ is larger than the O atom, not smaller."}'::jsonb, 'The second electron gain enthalpy of any element is positive, because of repulsion from the anion.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('af6d4759-1bab-54d2-9e48-4a074eb56c93', 'neet_ug', 'Chemistry', 'Amines', 'The number of structural isomers possible from the molecular formula C₃H₉N is:', '[{"id": "a", "text": "2"}, {"id": "b", "text": "3"}, {"id": "c", "text": "4"}, {"id": "d", "text": "5"}]'::jsonb, 'c', 'C₃H₉N has four amine isomers: two 1°, one 2° and one 3°.', 'The 1° amines are propan-1-amine and propan-2-amine. The 2° amine is N-methylethanamine, and the 3° amine is N,N-dimethylmethanamine (trimethylamine). That makes 4.', '{"a": "Counts only the primary amines.", "b": "Misses either the secondary or the tertiary amine.", "d": "There is no fifth saturated amine with this formula."}'::jsonb, 'C₃H₉N has 4 isomers: 2 primary, 1 secondary and 1 tertiary amine.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('28408c4e-092d-5407-92ce-23f4067d6a6f', 'neet_ug', 'Chemistry', 'Equilibrium', 'If the equilibrium constant for N₂(g) + O₂(g) ⇌ 2NO(g) is K, the equilibrium constant for ½N₂(g) + ½O₂(g) ⇌ NO(g) will be:', '[{"id": "a", "text": "K"}, {"id": "b", "text": "K²"}, {"id": "c", "text": "K^(1/2)"}, {"id": "d", "text": "½K"}]'::jsonb, 'c', 'Halving the coefficients of a reaction takes the square root of K.', 'K'' = [NO]/([N₂]^½[O₂]^½) = ([NO]²/[N₂][O₂])^½ = K^(1/2).', '{"a": "K changes when the stoichiometry changes.", "b": "K² applies when the equation is doubled.", "d": "K is not multiplied by the scaling factor; it is raised to that power."}'::jsonb, 'Multiplying an equation by n raises K to the power n; reversing it gives 1/K.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('e0182084-3c3b-5b6e-9073-6a0733352444', 'neet_ug', 'Chemistry', 'Equilibrium', 'Aqueous solution of which of the following compounds is the best conductor of electric current?', '[{"id": "a", "text": "Ammonia, NH₃"}, {"id": "b", "text": "Fructose, C₆H₁₂O₆"}, {"id": "c", "text": "Acetic acid, C₂H₄O₂"}, {"id": "d", "text": "Hydrochloric acid, HCl"}]'::jsonb, 'd', 'HCl is a strong electrolyte and ionises completely, giving the most ions.', 'Conductance depends on the number of ions. HCl ionises almost completely into H₃O⁺ and Cl⁻. NH₃ and acetic acid are weak electrolytes, and fructose does not ionise at all.', '{"a": "NH₃ is a weak base, so it gives few ions.", "b": "Fructose is a non-electrolyte.", "c": "Acetic acid ionises only slightly."}'::jsonb, 'Strong acids, strong bases and salts are strong electrolytes; H⁺ has the highest ionic mobility.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('7b7950bb-4af5-5218-b39e-5f3a78341c19', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'Strong reducing behaviour of H₃PO₂ is due to:', '[{"id": "a", "text": "High oxidation state of phosphorus"}, {"id": "b", "text": "Presence of two –OH groups and one P–H bond"}, {"id": "c", "text": "Presence of one –OH group and two P–H bonds"}, {"id": "d", "text": "High electron gain enthalpy of phosphorus"}]'::jsonb, 'c', 'H₃PO₂ has two P–H bonds (and one P–OH), which make it a strong reducing agent.', 'In hypophosphorous acid, P carries one =O, one –OH and two H atoms directly bonded. Oxyacids with P–H bonds are reducing, and having two such bonds makes H₃PO₂ a strong reductant (P is in the low +1 state).', '{"a": "P is in a low (+1) oxidation state, not a high one.", "b": "That describes H₃PO₃ (two –OH, one P–H).", "d": "Electron gain enthalpy has no bearing on reducing power here."}'::jsonb, 'Basicity of P oxyacids = number of P–OH groups: H₃PO₂ is monobasic and H₃PO₃ is dibasic.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('dd9ebb24-ce0b-5daf-abe2-77660ad5961d', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'Decreasing order of stability of O₂, O₂⁻, O₂⁺ and O₂²⁻ is:', '[{"id": "a", "text": "O₂ > O₂⁺ > O₂²⁻ > O₂⁻"}, {"id": "b", "text": "O₂⁻ > O₂²⁻ > O₂⁺ > O₂"}, {"id": "c", "text": "O₂⁺ > O₂ > O₂⁻ > O₂²⁻"}, {"id": "d", "text": "O₂²⁻ > O₂⁻ > O₂ > O₂⁺"}]'::jsonb, 'c', 'Stability follows bond order: O₂⁺ (2.5) > O₂ (2) > O₂⁻ (1.5) > O₂²⁻ (1).', 'By MO theory, O₂ has bond order 2. Removing an antibonding π* electron gives O₂⁺ (2.5). Adding π* electrons gives O₂⁻ (1.5) and O₂²⁻ (1.0). A higher bond order means a more stable species.', '{"a": "Puts O₂ above O₂⁺ and O₂²⁻ above O₂⁻, against the bond orders.", "b": "This is roughly the reverse of the bond-order order.", "d": "This is exactly the reverse order."}'::jsonb, 'Bond order = ½(Nb – Na); a higher bond order means a shorter, stronger and more stable bond.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('5d0486b6-a1fe-56b3-9919-d3f15f895c80', 'neet_ug', 'Chemistry', 'Some Basic Concepts of Chemistry', 'The number of water molecules is maximum in:', '[{"id": "a", "text": "18 gram of water"}, {"id": "b", "text": "18 moles of water"}, {"id": "c", "text": "18 molecules of water"}, {"id": "d", "text": "1.8 gram of water"}]'::jsonb, 'b', '18 moles of water contain 18 × N_A molecules, the largest number here.', '18 g = 1 mol = N_A molecules; 1.8 g = 0.1 N_A; 18 molecules is just 18. 18 mol = 18 × 6.022×10²³ ≈ 1.08×10²⁵ molecules, which is the largest.', '{"a": "Only 1 mol, i.e. 6.022×10²³ molecules.", "c": "Only 18 molecules.", "d": "Only 0.1 mol."}'::jsonb, 'Number of molecules = moles × 6.022×10²³.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('81715832-720e-5809-99e1-2566eab4d768', 'neet_ug', 'Chemistry', 'Chemical Bonding and Molecular Structure', 'In which of the following pairs, both the species are not isostructural?', '[{"id": "a", "text": "NH₃, PH₃"}, {"id": "b", "text": "XeF₄, XeO₄"}, {"id": "c", "text": "SiCl₄, PCl₄⁺"}, {"id": "d", "text": "Diamond, silicon carbide"}]'::jsonb, 'b', 'XeF₄ is square planar while XeO₄ is tetrahedral, so they differ in structure.', 'XeF₄ has 4 bond pairs and 2 lone pairs (sp³d²), giving a square planar shape. XeO₄ has 4 σ bonds and no lone pair (sp³), giving a tetrahedral shape. NH₃/PH₃ are both pyramidal, SiCl₄/PCl₄⁺ are both tetrahedral, and diamond/SiC are both tetrahedral 3-D networks.', '{"a": "Both are trigonal pyramidal.", "c": "Both are tetrahedral, with 4 bond pairs on the central atom.", "d": "SiC has a diamond-like tetrahedral network."}'::jsonb, 'XeF₂ is linear, XeF₄ is square planar, XeF₆ is distorted octahedral and XeO₃ is pyramidal.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('e7be3c8c-7eca-52cc-a8bf-d29671963352', 'neet_ug', 'Chemistry', 'Hydrocarbons', 'In the reaction with HCl, an alkene reacts in accordance with the Markovnikov''s rule, to give a product 1-chloro-1-methylcyclohexane. The possible alkene is:', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'c', 'Both methylenecyclohexane (A) and 1-methylcyclohexene (B) give the same 3° carbocation and hence 1-chloro-1-methylcyclohexane.', 'Markovnikov addition of H⁺ to methylenecyclohexane (to the =CH₂) or to 1-methylcyclohexene (to ring C-2) produces the tertiary 1-methylcyclohexyl cation. Cl⁻ then attacks C-1. So both A and B give the product, while 3-methylcyclohexene would give a 2° cation on a different carbon.', '{"a": "Correct but incomplete, because B also gives the product.", "b": "Correct but incomplete, because A also gives the product.", "d": "3-Methylcyclohexene gives a secondary chloride, not 1-chloro-1-methylcyclohexane."}'::jsonb, 'Markovnikov''s rule: H adds to the carbon with more H atoms, giving the more stable carbocation.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', '/pyq/ug/2015/14.webp'),
('c524669a-1c6a-5b41-a607-f979eb56503d', 'neet_ug', 'Chemistry', 'Redox Reactions', 'Assuming complete ionization, same moles of which of the following compounds will require the least amount of acidified KMnO₄ for complete oxidation?', '[{"id": "a", "text": "FeC₂O₄"}, {"id": "b", "text": "Fe(NO₂)₂"}, {"id": "c", "text": "FeSO₄"}, {"id": "d", "text": "FeSO₃"}]'::jsonb, 'c', 'Only Fe²⁺ is oxidised in FeSO₄ (1 e⁻ per formula unit), so it needs the least KMnO₄.', 'Count the electrons lost per formula unit. FeSO₄: Fe²⁺→Fe³⁺ = 1. FeSO₃: 1 + 2 (SO₃²⁻→SO₄²⁻) = 3. FeC₂O₄: 1 + 2 (C₂O₄²⁻→2CO₂) = 3. Fe(NO₂)₂: 1 + 2×2 (NO₂⁻→NO₃⁻) = 5. The fewest electrons need the least MnO₄⁻.', '{"a": "Oxalate is also oxidised, so 3 e⁻ in total.", "b": "Both nitrite ions are oxidised, so 5 e⁻ in total, the most.", "d": "Sulphite is also oxidised to sulphate, so 3 e⁻ in total."}'::jsonb, 'In acid, MnO₄⁻ → Mn²⁺ is a 5-electron change; it oxidises Fe²⁺, C₂O₄²⁻, NO₂⁻ and SO₃²⁻.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('9cfd4ab0-2024-5e58-b01d-a04516355070', 'neet_ug', 'Chemistry', 'Alcohols, Phenols and Ethers', 'Reaction of phenol with chloroform in presence of dilute sodium hydroxide finally introduces which one of the following functional group?', '[{"id": "a", "text": "–CHCl₂"}, {"id": "b", "text": "–CHO"}, {"id": "c", "text": "–CH₂Cl"}, {"id": "d", "text": "–COOH"}]'::jsonb, 'b', 'This is the Reimer–Tiemann reaction, which puts a –CHO group ortho to –OH (salicylaldehyde).', 'CHCl₃ with NaOH forms dichlorocarbene, which attacks the phenoxide ring at the ortho position to give a –CHCl₂ intermediate. Alkaline hydrolysis converts it to –CHO, so salicylaldehyde is formed.', '{"a": "–CHCl₂ is only an intermediate; it is hydrolysed.", "c": "No –CH₂Cl group is formed in this reaction.", "d": "–COOH is introduced by CCl₄/NaOH or by the Kolbe reaction, not by CHCl₃."}'::jsonb, 'Reimer–Tiemann: phenol + CHCl₃/NaOH gives salicylaldehyde; Kolbe: phenoxide + CO₂ gives salicylic acid.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('3a5c597b-dacd-57ad-9cb0-e41ecb5b56f0', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'Which of the statements given below is incorrect?', '[{"id": "a", "text": "ONF is isoelectronic with O₂N⁻"}, {"id": "b", "text": "OF₂ is an oxide of fluorine"}, {"id": "c", "text": "Cl₂O₇ is an anhydride of perchloric acid"}, {"id": "d", "text": "O₃ molecule is bent"}]'::jsonb, 'b', 'OF₂ is oxygen difluoride, a fluoride of oxygen, because F is more electronegative than O.', 'In OF₂ the more electronegative F carries the negative oxidation state (–1) and O is +2, so it is a fluoride of oxygen. ONF and NO₂⁻ both have 24 electrons. Dehydrating HClO₄ gives Cl₂O₇, and O₃ is bent (sp², with one lone pair on the central O).', '{"a": "True: ONF has 8+7+9 = 24 electrons and NO₂⁻ has 7+16+1 = 24.", "c": "True: 2HClO₄ – H₂O → Cl₂O₇.", "d": "True: O₃ is angular, about 117°."}'::jsonb, 'The more electronegative element is named last: OF₂ = oxygen difluoride.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('84d03fb7-17f9-5fea-83a7-2cc184b67c03', 'neet_ug', 'Chemistry', 'Coordination Compounds', 'The name of complex ion, [Fe(CN)₆]³⁻ is:', '[{"id": "a", "text": "Tricyanoferrate (III) ion"}, {"id": "b", "text": "Hexacyanidoferrate (III) ion"}, {"id": "c", "text": "Hexacyanoiron (III) ion"}, {"id": "d", "text": "Hexacyanitoferrate (III) ion"}]'::jsonb, 'b', 'Six cyanido ligands on Fe(III) in an anionic complex give hexacyanidoferrate(III).', 'Count the ligands (6 CN⁻ = hexacyanido). In an anionic complex the metal name ends in -ate, and for iron the Latin ''ferrate'' is used. The oxidation state is x – 6 = –3, so x = +3.', '{"a": "There are six CN⁻ ligands, not three.", "c": "An anionic complex must use ''ferrate'', not ''iron''.", "d": "''Cyanito'' is not the IUPAC ligand name; it is ''cyanido''."}'::jsonb, 'Anionic complexes take the -ate suffix: Fe → ferrate, Cu → cuprate, Ag → argentate, Pb → plumbate.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('535da0dd-7fae-58a6-a942-308fde7f6c23', 'neet_ug', 'Chemistry', 'Some Basic Concepts of Chemistry', 'If avogadro number N_A, is changed from 6.022 × 10²³ mol⁻¹ to 6.022 × 10²⁰ mol⁻¹, this would change:', '[{"id": "a", "text": "the ratio of chemical species to each other in a balanced equation"}, {"id": "b", "text": "the ratio of elements to each other in a compound"}, {"id": "c", "text": "the definition of mass in units of grams"}, {"id": "d", "text": "the mass of one mole of carbon"}]'::jsonb, 'd', 'A mole would contain 1000 times fewer atoms, so the mass of one mole of carbon would fall from 12 g to 12 mg.', 'Molar mass = N_A × mass of one particle. With N_A reduced by 10³, 1 mol of C would weigh 12 × 10⁻³ g. Stoichiometric ratios, compound composition and the gram itself do not depend on N_A.', '{"a": "Mole ratios in an equation equal the particle ratios, which do not change.", "b": "The fixed composition of a compound does not depend on N_A.", "c": "The gram is defined independently of N_A."}'::jsonb, 'One mole contains 6.022 × 10²³ particles; molar mass in g equals the atomic or molecular mass in u.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('56c51172-ffb3-567a-938a-8df287b9d75b', 'neet_ug', 'Chemistry', 'Organic Chemistry – Some Basic Principles and Techniques', 'Which of the following statements is not correct for a nucleophile?', '[{"id": "a", "text": "Nucleophiles attack low e⁻ density sites"}, {"id": "b", "text": "Nucleophiles are not electron seeking"}, {"id": "c", "text": "Nucleophile is a Lewis acid"}, {"id": "d", "text": "Ammonia is a nucleophile"}]'::jsonb, 'c', 'Nucleophiles donate an electron pair, so they are Lewis bases, not Lewis acids.', 'A nucleophile (''nucleus-loving'') is electron-rich and attacks electron-deficient centres by donating a lone pair or π electrons. This is Lewis-base behaviour. NH₃, with its lone pair, is a typical neutral nucleophile.', '{"a": "True: they attack electron-poor (δ+) sites.", "b": "True: electrophiles are the electron-seeking species.", "d": "True: the lone pair on N makes NH₃ a nucleophile."}'::jsonb, 'Nucleophile = Lewis base (electron-pair donor); electrophile = Lewis acid (electron-pair acceptor).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('e121c333-04ec-5c58-acb1-36c74980c92c', 'neet_ug', 'Chemistry', 'Coordination Compounds', 'The hybridization involved in complex [Ni(CN)₄]²⁻ is (At. No. Ni = 28)', '[{"id": "a", "text": "d²sp²"}, {"id": "b", "text": "d²sp³"}, {"id": "c", "text": "dsp²"}, {"id": "d", "text": "sp³"}]'::jsonb, 'c', 'Strong-field CN⁻ pairs the 3d⁸ electrons of Ni²⁺, leaving one 3d orbital free, so the hybridisation is dsp² (square planar).', 'Ni²⁺ is 3d⁸. CN⁻ forces pairing into four 3d orbitals, leaving one empty 3d orbital. That orbital plus 4s and two 4p orbitals form dsp² hybrids for four ligands, giving a square planar, diamagnetic complex.', '{"a": "d²sp² is not a valid hybridisation for a four-coordinate complex.", "b": "d²sp³ is for octahedral six-coordinate complexes.", "d": "sp³ occurs with weak-field ligands, e.g. [NiCl₄]²⁻."}'::jsonb, '[Ni(CN)₄]²⁻ is square planar and diamagnetic, [NiCl₄]²⁻ is tetrahedral and paramagnetic, and [Ni(CO)₄] is tetrahedral.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('676a0811-679c-5b4b-89c9-69a03afece39', 'neet_ug', 'Chemistry', 'Thermodynamics', 'The heat of combustion of carbon to CO₂ is –393.5 kJ/mol. The heat released upon formation of 35.2 g of CO₂ from carbon and oxygen gas is:', '[{"id": "a", "text": "–630 kJ"}, {"id": "b", "text": "–3.15 kJ"}, {"id": "c", "text": "–315 kJ"}, {"id": "d", "text": "+315 kJ"}]'::jsonb, 'c', '35.2 g CO₂ = 0.8 mol, and 0.8 × (–393.5) ≈ –315 kJ.', 'Moles of CO₂ = 35.2/44 = 0.80 mol. Each mole formed releases 393.5 kJ, so ΔH = 0.80 × (–393.5) = –314.8 ≈ –315 kJ.', '{"a": "This is about 1.6 mol worth of heat (wrong mole count).", "b": "Off by a factor of 100.", "d": "Formation of CO₂ is exothermic, so the sign must be negative."}'::jsonb, 'The standard enthalpy of combustion of C(graphite) equals the standard enthalpy of formation of CO₂.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('2ae1edec-f68a-5754-ba53-0fe371571e98', 'neet_ug', 'Chemistry', 'Some Basic Concepts of Chemistry', '20.0 g of a magnesium carbonate sample decomposes on heating to give carbon dioxide and 8.0 g magnesium oxide. What will be the percentage purity of magnesium carbonate in the sample? (At. Wt.: Mg = 24)', '[{"id": "a", "text": "60"}, {"id": "b", "text": "84"}, {"id": "c", "text": "75"}, {"id": "d", "text": "96"}]'::jsonb, 'b', '8.0 g MgO = 0.2 mol, which needs 0.2 × 84 = 16.8 g MgCO₃, so purity = 16.8/20 = 84%.', 'MgCO₃ → MgO + CO₂ (1:1). n(MgO) = 8.0/40 = 0.20 mol, so the pure MgCO₃ present = 0.20 × 84 = 16.8 g. Purity = 16.8/20.0 × 100 = 84%.', '{"a": "Does not follow from the 1:1 stoichiometry.", "c": "Would need 15 g MgCO₃, i.e. about 7.1 g MgO.", "d": "Would need about 9.1 g MgO."}'::jsonb, '% purity = (mass of pure substance from stoichiometry ÷ mass of sample) × 100.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('9b623e35-453d-5db6-bd02-686c0691d899', 'neet_ug', 'Chemistry', 'Solutions', 'What is the mole fraction of the solute in a 1.00 m aqueous solution?', '[{"id": "a", "text": "0.0354"}, {"id": "b", "text": "0.0177"}, {"id": "c", "text": "0.177"}, {"id": "d", "text": "1.770"}]'::jsonb, 'b', '1 mol solute in 1000 g water (55.5 mol) gives x = 1/56.5 ≈ 0.0177.', 'In 1.00 m solution there is 1 mol solute per 1 kg water. n(H₂O) = 1000/18 = 55.56 mol. x(solute) = 1/(1 + 55.56) = 0.0177.', '{"a": "Twice the correct value.", "c": "Ten times the correct value.", "d": "A mole fraction cannot exceed 1."}'::jsonb, 'Molality is moles of solute per kg of solvent and does not depend on temperature.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('0380f58f-210d-5575-a6c9-14754fc1ad86', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'The stability of +1 oxidation state among Al, Ga, In and Tl increases in the sequence:', '[{"id": "a", "text": "Tl < In < Ga < Al"}, {"id": "b", "text": "In < Tl < Ga < Al"}, {"id": "c", "text": "Ga < In < Al < Tl"}, {"id": "d", "text": "Al < Ga < In < Tl"}]'::jsonb, 'd', 'Because of the inert pair effect, the stability of +1 rises down group 13: Al < Ga < In < Tl.', 'Going down group 13, the ns² electrons are held more tightly (poor shielding by d and f electrons), so they are less available for bonding. The lower +1 state becomes more stable, and it is the most stable for Tl.', '{"a": "This is the reverse order.", "b": "Places In below Tl and Al at the top, which is wrong.", "c": "Al has the least stable +1 state, so it cannot come before In."}'::jsonb, 'Inert pair effect: Tl⁺ is more stable than Tl³⁺; similarly Pb²⁺ is more stable than Pb⁴⁺ in group 14.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('d6897cb6-4343-58d4-9a84-614f0bd2dbac', 'neet_ug', 'Chemistry', 'Organic Chemistry – Some Basic Principles and Techniques', 'Two possible stereo-structures of CH₃CHOH.COOH, which are optically active, are called:', '[{"id": "a", "text": "Enantiomers"}, {"id": "b", "text": "Mesomers"}, {"id": "c", "text": "Diastereomers"}, {"id": "d", "text": "Atropisomers"}]'::jsonb, 'a', 'Lactic acid has one chiral carbon, and its two forms are non-superimposable mirror images, i.e. enantiomers.', 'C-2 of lactic acid carries four different groups (H, OH, CH₃, COOH). With a single stereocentre, the two optically active forms (d and l) are mirror images of each other, which is the definition of enantiomers.', '{"b": "''Mesomers'' refers to resonance structures, not stereoisomers.", "c": "Diastereomers need at least two stereocentres (non-mirror-image stereoisomers).", "d": "Atropisomers come from restricted rotation about a single bond, e.g. in biphenyls."}'::jsonb, 'A molecule with n chiral centres has at most 2ⁿ stereoisomers; with one centre, these are a single pair of enantiomers.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('cdb14fd0-5746-5a7b-8204-79e17cc32fad', 'neet_ug', 'Chemistry', 'Amines', 'The following reaction [aniline + benzoyl chloride, NaOH → benzanilide; see figure] is known by the name:', '[{"id": "a", "text": "Acetylation reaction"}, {"id": "b", "text": "Schotten-Baumen reaction"}, {"id": "c", "text": "Friedel-Craft''s reaction"}, {"id": "d", "text": "Perkin''s reaction"}]'::jsonb, 'b', 'Benzoylation of aniline with benzoyl chloride in aqueous NaOH is the Schotten–Baumann reaction.', 'Aniline attacks the acyl carbon of C₆H₅COCl, giving N-phenylbenzamide and HCl. NaOH neutralises the HCl. Benzoylation under these aqueous alkaline conditions is called the Schotten–Baumann reaction.', '{"a": "Acetylation adds a CH₃CO– group, but benzoyl C₆H₅CO– is added here.", "c": "Friedel–Crafts acylation adds to a ring carbon using AlCl₃, not to N.", "d": "Perkin''s reaction condenses an aromatic aldehyde with an anhydride."}'::jsonb, 'Acylation of amines (–NH₂ → –NHCOR) reduces the activating effect of the amino group.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', '/pyq/ug/2015/30.webp'),
('0a8ee220-e138-5bbf-8816-5f6e656e032e', 'neet_ug', 'Chemistry', 'Coordination Compounds', 'The sum of coordination number and oxidation number of the metal M in the complex [M(en)₂(C₂O₄)]Cl (where en is ethylenediamine) is:', '[{"id": "a", "text": "7"}, {"id": "b", "text": "8"}, {"id": "c", "text": "9"}, {"id": "d", "text": "6"}]'::jsonb, 'c', 'There are two bidentate en ligands and one bidentate oxalate (CN = 6), and M is +3, so the sum is 9.', 'CN = 2×2 (en) + 2 (C₂O₄²⁻) = 6. Charge balance: x + 0 – 2 = +1 (to balance Cl⁻), so x = +3. Sum = 6 + 3 = 9.', '{"a": "Treats the ligands as fewer donor sites or uses the wrong oxidation state.", "b": "Uses oxidation state +2.", "d": "Gives only the coordination number."}'::jsonb, 'en and C₂O₄²⁻ are bidentate; EDTA⁴⁻ is hexadentate.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('d44c12eb-400b-528d-aff9-880872600db3', 'neet_ug', 'Chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 'Reaction of carbonyl compound with one of the following reagents involves nucleophilic addition followed by elimination of water. The reagent is:', '[{"id": "a", "text": "hydrocyanic acid"}, {"id": "b", "text": "sodium hydrogen sulphite"}, {"id": "c", "text": "a Grignard reagent"}, {"id": "d", "text": "hydrazine in presence of feebly acidic solution"}]'::jsonb, 'd', 'Hydrazine adds to C=O and then loses water to form a hydrazone (C=N–NH₂).', 'Ammonia derivatives (NH₂–Z) add to the carbonyl carbon in weakly acidic medium to give a carbinolamine, which dehydrates to C=N–Z. HCN, NaHSO₃ and RMgX give simple addition products without losing water.', '{"a": "HCN gives a cyanohydrin by addition only.", "b": "NaHSO₃ gives a bisulphite addition product, with no water lost.", "c": "A Grignard reagent gives an alkoxide (alcohol after hydrolysis), with no elimination."}'::jsonb, 'Hydroxylamine gives oximes, hydrazine gives hydrazones, phenylhydrazine gives phenylhydrazones, and semicarbazide gives semicarbazones (all addition–elimination).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('df2e033a-c430-50c7-9fb4-b15821135636', 'neet_ug', 'Chemistry', 'Aldehydes, Ketones and Carboxylic Acids', 'Which one of the following esters gets hydrolysed most easily under alkaline conditions?', '[{"id": "a", "text": "Option (1) in figure"}, {"id": "b", "text": "Option (2) in figure"}, {"id": "c", "text": "Option (3) in figure"}, {"id": "d", "text": "Option (4) in figure"}]'::jsonb, 'c', 'The p-nitrophenyl ester hydrolyses fastest, because –NO₂ makes the carbonyl more electrophilic and the phenoxide a better leaving group.', 'Alkaline hydrolysis is a nucleophilic attack of OH⁻ on the ester C=O, followed by loss of ArO⁻. The strongly electron-withdrawing –NO₂ at the para position stabilises the leaving p-nitrophenoxide by resonance, which speeds the reaction. –OCH₃ donates electrons and slows it, and –Cl only mildly helps.', '{"a": "Unsubstituted phenyl acetate has no activating group.", "b": "–Cl withdraws electrons only weakly (–I partly offset by +R), so it is slower than –NO₂.", "d": "–OCH₃ donates electrons (+R) and makes hydrolysis slowest."}'::jsonb, 'Electron-withdrawing groups increase the reactivity of acyl derivatives towards nucleophilic attack.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', '/pyq/ug/2015/33.webp'),
('4b3a9a0d-128d-5317-8c21-aaa7920cb212', 'neet_ug', 'Chemistry', 'Chemical Kinetics', 'The rate constant of the reaction A → B is 0.6 × 10⁻³ mole per second. If the concentration of A is 5 M, then concentration of B after 20 minutes is:', '[{"id": "a", "text": "0.36 M"}, {"id": "b", "text": "0.72 M"}, {"id": "c", "text": "1.08 M"}, {"id": "d", "text": "3.60 M"}]'::jsonb, 'b', 'The units mol L⁻¹ s⁻¹ show a zero-order reaction, so [B] = kt = 0.6×10⁻³ × 1200 = 0.72 M.', 'For a zero-order reaction, the amount converted is x = kt, independent of [A]₀. t = 20 × 60 = 1200 s, so x = 0.6×10⁻³ × 1200 = 0.72 M. This is less than 5 M, so A is not exhausted.', '{"a": "Uses only half the time.", "c": "Uses 30 min instead of 20 min.", "d": "Off by a factor of 5 (multiplies by [A]₀)."}'::jsonb, 'Zero order: [A] = [A]₀ – kt, t½ = [A]₀/2k, and k has units of mol L⁻¹ s⁻¹.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('bd450351-8318-5c13-9330-8073a8742de1', 'neet_ug', 'Chemistry', 'Equilibrium', 'What is the pH of the resulting solution when equal volumes of 0.1 M NaOH and 0.01 M HCl are mixed?', '[{"id": "a", "text": "7.0"}, {"id": "b", "text": "1.04"}, {"id": "c", "text": "12.65"}, {"id": "d", "text": "2.0"}]'::jsonb, 'c', 'Excess OH⁻ = (0.1 – 0.01)/2 = 0.045 M, so pOH ≈ 1.35 and pH ≈ 12.65.', 'Take V of each. Excess OH⁻ = 0.09V in a total of 2V, so [OH⁻] = 0.045 M. pOH = –log 0.045 = 1.35, and pH = 14 – 1.35 = 12.65.', '{"a": "The amounts are not equal, so the mixture is not neutral.", "b": "Treats the solution as acidic.", "d": "Treats the solution as acidic; NaOH is in excess."}'::jsonb, 'When a strong acid and base are mixed, find the excess moles, divide by the total volume, then take pH or pOH.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('41c0b48d-d592-51cf-a348-d300afcafdd4', 'neet_ug', 'Chemistry', 'Coordination Compounds', 'Number of possible isomers for the complex [Co(en)₂Cl₂]Cl will be: (en = ethylenediamine)', '[{"id": "a", "text": "3"}, {"id": "b", "text": "4"}, {"id": "c", "text": "2"}, {"id": "d", "text": "1"}]'::jsonb, 'a', '[Co(en)₂Cl₂]⁺ has trans (optically inactive) and cis (a pair of enantiomers) forms, so 3 stereoisomers.', 'The octahedral M(AA)₂B₂ type shows cis and trans geometrical isomers. The trans form has a mirror plane. The cis form is chiral and exists as d and l enantiomers. The total is 1 + 2 = 3.', '{"b": "There is no fourth stereoisomer.", "c": "Counts only the geometrical isomers and ignores the optical pair.", "d": "Ignores isomerism completely."}'::jsonb, 'cis-[Co(en)₂Cl₂]⁺ is optically active, while the trans form is optically inactive.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('7c6222b2-ee12-57ea-90c9-ab6c4222dfe3', 'neet_ug', 'Chemistry', 'The p-Block Elements', 'The variation of the boiling points of the hydrogen halides is in the order HF > HI > HBr > HCl. What explains the higher boiling point of hydrogen fluoride?', '[{"id": "a", "text": "The bond energy of HF molecules is greater than in other hydrogen halides"}, {"id": "b", "text": "The effect of nuclear shielding is much reduced in fluorine which polarises the HF molecule"}, {"id": "c", "text": "The electronegativity of fluorine is much higher than for other elements in the group"}, {"id": "d", "text": "There is strong hydrogen bonding between HF molecules"}]'::jsonb, 'd', 'Intermolecular hydrogen bonding between HF molecules raises its boiling point far above the trend.', 'Boiling point depends on intermolecular forces, not on bond strength. Small, highly electronegative F forms strong H–F···H hydrogen bonds (zig-zag chains), which take extra energy to break. HCl→HI rises only because of growing van der Waals forces.', '{"a": "Intramolecular bond energy does not decide the boiling point.", "b": "This is not the main reason for the anomaly.", "c": "High electronegativity is why the H-bond forms, but the H-bonding itself is the direct explanation."}'::jsonb, 'Anomalous boiling points of HF, H₂O and NH₃ are due to hydrogen bonding.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('6fa317cc-ee26-59fd-96e8-4dc705046e34', 'neet_ug', 'Chemistry', 'Some Basic Concepts of Chemistry', 'What is the mass of the precipitate formed when 50 mL of 16.9% solution of AgNO₃ is mixed with 50 mL of 5.8% NaCl solution? (Ag = 107.8, N = 14, O = 16, Na = 23, Cl = 35.5)', '[{"id": "a", "text": "7 g"}, {"id": "b", "text": "14 g"}, {"id": "c", "text": "28 g"}, {"id": "d", "text": "3.5 g"}]'::jsonb, 'a', 'About 0.05 mol each of AgNO₃ and NaCl gives about 0.05 mol AgCl ≈ 7 g.', 'AgNO₃ = 0.169 × 50 = 8.45 g, and 8.45/169.8 = 0.0498 mol. NaCl = 0.058 × 50 = 2.9 g, and 2.9/58.5 = 0.0496 mol, which is limiting. AgCl formed = 0.0496 × 143.3 ≈ 7.1 g ≈ 7 g.', '{"b": "Double the true amount (uses 100 mL of each).", "c": "Four times the true amount.", "d": "Half the true amount."}'::jsonb, 'In a precipitation problem, find the limiting reagent first; w/v% means g per 100 mL.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('5f94ebb8-10b9-50cd-965e-34a327f66239', 'neet_ug', 'Chemistry', 'Hydrocarbons', 'The oxidation of benzene by V₂O₅ in the presence of air produces :', '[{"id": "a", "text": "benzoic acid"}, {"id": "b", "text": "benzaldehyde"}, {"id": "c", "text": "benzoic anhydride"}, {"id": "d", "text": "maleic anhydride"}]'::jsonb, 'd', 'Catalytic air oxidation of benzene over V₂O₅ breaks the ring and gives maleic anhydride.', 'At about 773 K over V₂O₅, benzene is oxidised by air with cleavage of the ring. The four-carbon cis-butenedioic fragment cyclises to maleic anhydride, with CO₂ and water as by-products. No carbon substituent is present on benzene, so benzoic acid or benzaldehyde cannot form.', '{"a": "Benzoic acid needs a side chain (e.g. toluene) to oxidise.", "b": "Benzaldehyde comes from controlled oxidation of toluene (Etard reaction), not benzene.", "c": "Benzoic anhydride would need a C₆H₅CO unit, which benzene lacks."}'::jsonb, 'Benzene + O₂ / V₂O₅, 773 K → maleic anhydride (ring cleavage).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('79cba3ec-cfc5-5234-b8c9-b99159bb515d', 'neet_ug', 'Chemistry', 'Amines', 'Method by which Aniline cannot be prepared is :-', '[{"id": "a", "text": "reduction of nitrobenzene with H₂/Pd in ethanol"}, {"id": "b", "text": "potassium salt of phthalimide treated with chlorobenzene followed by hydrolysis with aqueous NaOH solution"}, {"id": "c", "text": "hydrolysis of phenylisocyanide with acidic solution"}, {"id": "d", "text": "degradation of benzamide with bromine in alkaline solution"}]'::jsonb, 'b', 'Gabriel synthesis fails for aryl amines because aryl halides do not undergo SN2 with phthalimide anion.', 'The C–Cl bond of chlorobenzene has partial double-bond character from resonance and the ring blocks backside attack, so the phthalimide anion cannot displace chloride. Hence Gabriel phthalimide synthesis cannot give aniline. The other routes (catalytic reduction, acid hydrolysis of C₆H₅NC, Hofmann bromamide degradation of C₆H₅CONH₂) all give aniline.', '{"a": "Catalytic hydrogenation reduces –NO₂ to –NH₂, giving aniline.", "c": "C₆H₅NC + 2H₂O/H⁺ → C₆H₅NH₂ + HCOOH, so aniline forms.", "d": "Hofmann bromamide reaction of benzamide gives aniline (one carbon less)."}'::jsonb, 'Gabriel synthesis gives only primary aliphatic amines, never aromatic amines.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('d0c4d8e3-4385-53b4-bd6b-742c0ea67b54', 'neet_ug', 'Chemistry', 'Haloalkanes and Haloarenes', 'Which of the following reaction(s) can be used for the preparation of alkyl halides ?
(I) CH₃CH₂OH + HCl —(anh. ZnCl₂)→
(II) CH₃CH₂OH + HCl →
(III) (CH₃)₃COH + HCl →
(IV) (CH₃)₂CHOH + HCl —(anh. ZnCl₂)→', '[{"id": "a", "text": "(IV) only"}, {"id": "b", "text": "(III) and (IV) only"}, {"id": "c", "text": "(I), (III) and (IV) only"}, {"id": "d", "text": "(I) and (II) only"}]'::jsonb, 'c', 'Primary and secondary alcohols need anhydrous ZnCl₂ with HCl, while tertiary alcohols react with conc. HCl alone.', 'ZnCl₂ (Groves'' process) is needed to make the OH a better leaving group for 1° and 2° alcohols, so (I) and (IV) work. Tertiary butanol forms a stable 3° carbocation and reacts readily with HCl even without catalyst, so (III) works. Ethanol with HCl alone (II) does not react appreciably.', '{"a": "Misses (I) and (III), which also give alkyl halides.", "b": "Leaves out (I), where ZnCl₂ is present.", "d": "(II) is ineffective without ZnCl₂."}'::jsonb, 'Reactivity of alcohols with HX: 3° > 2° > 1°; Lucas reagent = conc. HCl + anhydrous ZnCl₂.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('80f25127-fc36-5b5e-ac36-622e869a51db', 'neet_ug', 'Botany', 'Biological Classification', 'Which one is a wrong statement ?', '[{"id": "a", "text": "Brown algae have chlorophyll a and c, and fucoxanthin"}, {"id": "b", "text": "Archegonia are found in Bryophyta, Pteridophyta and Gymnosperms"}, {"id": "c", "text": "Mucor has biflagellate zoospores"}, {"id": "d", "text": "Haploid endosperm is typical feature of gymnosperms"}]'::jsonb, 'c', 'Mucor reproduces asexually by non-motile sporangiospores, not flagellated zoospores.', 'Mucor is a terrestrial phycomycete whose asexual spores are aplanospores (sporangiospores) borne in sporangia; motile biflagellate zoospores occur in aquatic forms like Albugo or algae. The other statements are correct: Phaeophyceae have chl a, c and fucoxanthin; archegonia occur in bryophytes, pteridophytes and gymnosperms; gymnosperm endosperm is the haploid female gametophyte.', '{"a": "True: brown algae have chlorophyll a, c and fucoxanthin.", "b": "True: all three groups (archegoniates) bear archegonia.", "d": "True: gymnosperm endosperm is haploid female gametophyte tissue formed before fertilisation."}'::jsonb, 'Mucor, Rhizopus: non-motile sporangiospores; zygospores in sexual reproduction.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('65841840-af83-500a-8b8d-ab963bd4ee94', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Which of the following structures is not found in prokaryotic cells?', '[{"id": "a", "text": "Plasma membrane"}, {"id": "b", "text": "Nuclear envelope"}, {"id": "c", "text": "Ribosome"}, {"id": "d", "text": "Mesosome"}]'::jsonb, 'b', 'Prokaryotes lack a membrane-bound nucleus, so there is no nuclear envelope.', 'In prokaryotes the genetic material lies naked in the cytoplasm as a nucleoid, with no nuclear membrane. They do have a plasma membrane, 70S ribosomes and mesosomes (infoldings of the plasma membrane).', '{"a": "All cells have a plasma membrane.", "c": "Prokaryotes have 70S ribosomes.", "d": "Mesosomes are characteristic prokaryotic membrane infoldings."}'::jsonb, 'Prokaryotic genome = nucleoid, not enclosed by a nuclear envelope.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('724de423-a1cf-5590-af33-29efc9bb54f0', 'neet_ug', 'Zoology', 'Body Fluids and Circulation', 'Which one of the following animals has two separate circulatory pathways ?', '[{"id": "a", "text": "Shark"}, {"id": "b", "text": "Frog"}, {"id": "c", "text": "Lizard"}, {"id": "d", "text": "Whale"}]'::jsonb, 'd', 'A whale, being a mammal, has a four-chambered heart with fully separate pulmonary and systemic circuits.', 'Mammals and birds have complete double circulation: oxygenated and deoxygenated blood never mix, giving two separate pathways (pulmonary and systemic). Fishes have single circulation, while amphibians and most reptiles have incompletely separated (mixed) double circulation.', '{"a": "Fishes have a two-chambered heart and single circulation.", "b": "Frogs have a three-chambered heart; blood mixes in the single ventricle.", "c": "Lizards have an incompletely divided ventricle, so circuits are not fully separate."}'::jsonb, 'Complete double circulation: birds and mammals; incomplete: amphibians and reptiles.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('d13342a0-11fe-593a-bbbb-870766a0b380', 'neet_ug', 'Botany', 'Ecosystem', 'Most animals that live in deep oceanic waters are:', '[{"id": "a", "text": "Detritivores"}, {"id": "b", "text": "Primary consumers"}, {"id": "c", "text": "Secondary consumers"}, {"id": "d", "text": "Tertiary consumers"}]'::jsonb, 'a', 'No light reaches the deep sea, so producers are absent and animals depend on sinking detritus.', 'Photosynthesis cannot occur in the aphotic deep ocean, so there is no local primary production to support herbivores. Most deep-sea animals feed on organic debris (marine snow) falling from the upper layers, making them detritivores.', '{"b": "Primary consumers need producers, which are absent in the dark depths.", "c": "Predators exist but are fewer than the detritus-feeders supporting the food web.", "d": "Top carnivores are the fewest in any ecosystem."}'::jsonb, 'Deep-sea food webs are detritus-based because the aphotic zone lacks producers.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('78e3b48a-3763-50e0-866c-499360cf107e', 'neet_ug', 'Botany', 'Organisms and Populations', 'An association of individuals of different species living in the same habitat and having functional interactions is :', '[{"id": "a", "text": "Population"}, {"id": "b", "text": "Ecological niche"}, {"id": "c", "text": "Biotic community"}, {"id": "d", "text": "Ecosystem"}]'::jsonb, 'c', 'Populations of different species interacting in one habitat make up a biotic community.', 'A population is a group of one species, whereas a community comprises populations of several species living together and interacting. An ecosystem adds the abiotic environment, and a niche is the functional role of a single species.', '{"a": "A population consists of a single species.", "b": "A niche is the role and requirements of one species.", "d": "An ecosystem includes abiotic components too, not just the interacting species."}'::jsonb, 'Community = all interacting populations of different species in an area.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('f55d3245-f4f0-5859-b2c0-719a2da51a74', 'neet_ug', 'Botany', 'Photosynthesis in Higher Plants', 'The oxygen evolved during photosynthesis comes from water molecules. Which one of the following pairs of elements is involved in this reaction?', '[{"id": "a", "text": "Magnesium and Chlorine"}, {"id": "b", "text": "Manganese and Chlorine"}, {"id": "c", "text": "Manganese and Potassium"}, {"id": "d", "text": "Magnesium and Molybdenum"}]'::jsonb, 'b', 'The water-splitting (oxygen-evolving) complex of PS II requires Mn²⁺ and Cl⁻.', 'Photolysis of water occurs at the oxygen-evolving complex on the lumen side of PS II, which contains a manganese cluster and needs chloride ions as cofactors. Thus Mn and Cl are directly involved in releasing O₂ from water.', '{"a": "Mg is in chlorophyll but not in the water-splitting complex.", "c": "Potassium regulates stomata, not photolysis.", "d": "Mo is needed for nitrogenase and nitrate reductase."}'::jsonb, 'Water splitting at PS II: 2H₂O → 4H⁺ + O₂ + 4e⁻, aided by Mn and Cl.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('aea751a2-bb32-53ad-92ff-83a62fd81448', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'Axile placentation is present in :', '[{"id": "a", "text": "Argemone"}, {"id": "b", "text": "Dianthus"}, {"id": "c", "text": "Lemon"}, {"id": "d", "text": "Pea"}]'::jsonb, 'c', 'Lemon (citrus) has a multilocular ovary with ovules on a central axis: axile placentation.', 'In axile placentation the ovary is divided into chambers and ovules attach to the central axis, as in China rose, tomato and lemon. Argemone shows parietal, Dianthus free-central and pea marginal placentation.', '{"a": "Argemone (and mustard) show parietal placentation.", "b": "Dianthus and Primrose show free central placentation.", "d": "Pea shows marginal placentation."}'::jsonb, 'Axile: China rose, tomato, lemon; Parietal: mustard, Argemone; Free central: Dianthus, Primrose; Basal: sunflower, marigold.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('8019578d-9744-5833-86cd-b35ac9091976', 'neet_ug', 'Botany', 'Ecosystem', 'In which of the following both pairs have correct combination :', '[{"id": "a", "text": "Gaseous nutrient cycle – Sulphur and Phosphorus; Sedimentary nutrient cycle – Carbon and Nitrogen"}, {"id": "b", "text": "Gaseous nutrient cycle – Carbon and Nitrogen; Sedimentary nutrient cycle – Sulphur and Phosphorus"}, {"id": "c", "text": "Gaseous nutrient cycle – Carbon and sulphur; Sedimentary nutrient cycle – Nitrogen and phosphorus"}, {"id": "d", "text": "Gaseous nutrient cycle – Nitrogen and sulphur; Sedimentary nutrient cycle – Carbon and Phosphorus"}]'::jsonb, 'b', 'Carbon and nitrogen cycle mainly through the atmosphere, while sulphur and phosphorus reservoirs lie in the Earth''s crust.', 'Nutrient cycles are gaseous when the main reservoir is the atmosphere (C, N) and sedimentary when it is the lithosphere (P, S). Only option (2) places both pairs correctly.', '{"a": "Reverses the two categories.", "c": "Nitrogen is a gaseous cycle and sulphur is sedimentary.", "d": "Carbon is gaseous and sulphur is sedimentary."}'::jsonb, 'Gaseous cycles: C, N (atmospheric reservoir); sedimentary: P, S (crustal reservoir).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('16e45ab4-40de-5704-b4f6-652327666a24', 'neet_ug', 'Zoology', 'Neural Control and Coordination', 'In mammalian eye, the ''fovea'' is the center of the visual field, where :', '[{"id": "a", "text": "more rods than cones are found."}, {"id": "b", "text": "high density of cones occur, but has no rods"}, {"id": "c", "text": "the optic nerve leaves the eye"}, {"id": "d", "text": "only rods are present"}]'::jsonb, 'b', 'The fovea is a thinned retinal spot packed with cones and devoid of rods, giving the sharpest vision.', 'Lateral to the blind spot lies the macula lutea, whose central pit, the fovea, contains only cones densely packed. It is the point of greatest visual acuity. The optic nerve exits at the blind spot, which has no photoreceptors.', '{"a": "Rods dominate the peripheral retina, not the fovea.", "c": "That describes the blind spot (optic disc).", "d": "The fovea has no rods at all."}'::jsonb, 'Fovea: only cones, highest acuity; blind spot: no photoreceptors.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('e22c4fdc-9e02-5f3c-b9e6-0ca2960b6082', 'neet_ug', 'Botany', 'Biological Classification', 'Choose the wrong statement :', '[{"id": "a", "text": "Yeast is unicellular and useful in fermentation"}, {"id": "b", "text": "Penicillium is multicellular and produces antibiotics"}, {"id": "c", "text": "Neurospora is used in the study of biochemical genetics"}, {"id": "d", "text": "Morels and truffles are poisonous mushrooms"}]'::jsonb, 'd', 'Morels and truffles are edible ascomycetes, not poisonous mushrooms.', 'Morels (Morchella) and truffles are prized edible fungi of class Ascomycetes. Yeast is unicellular and ferments sugars, Penicillium is a multicellular mould yielding penicillin, and Neurospora was used by Beadle and Tatum in biochemical genetics.', '{"a": "True: yeast is unicellular and used in fermentation.", "b": "True: Penicillium is filamentous and produces penicillin.", "c": "True: Neurospora is a model for biochemical and genetic studies."}'::jsonb, 'Edible ascomycetes: morels, truffles; Neurospora: one gene–one enzyme work.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('7c74bac2-10cd-5519-a676-2ac9343ec665', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Which of the following are not membrane-bound?', '[{"id": "a", "text": "Mesosomes"}, {"id": "b", "text": "Vacuoles"}, {"id": "c", "text": "Ribosomes"}, {"id": "d", "text": "Lysosomes"}]'::jsonb, 'c', 'Ribosomes are made of rRNA and protein and have no membrane.', 'Ribosomes are non-membranous particles of RNA and protein found in both prokaryotes and eukaryotes. Vacuoles (tonoplast) and lysosomes are single-membrane organelles, and mesosomes are infoldings of the plasma membrane.', '{"a": "Mesosomes are formed from the plasma membrane.", "b": "Vacuoles are bounded by the tonoplast.", "d": "Lysosomes are single-membrane vesicles with hydrolases."}'::jsonb, 'Non-membranous organelles: ribosomes, centrioles (and cytoskeleton).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('6d352eaf-cf96-57b5-8f01-6218a46708a7', 'neet_ug', 'Botany', 'Organisms and Populations', 'In which of the following interactions both partners are adversely affected ?', '[{"id": "a", "text": "Mutualism"}, {"id": "b", "text": "Competition"}, {"id": "c", "text": "Predation"}, {"id": "d", "text": "Parasitism"}]'::jsonb, 'b', 'In competition both species lose (−/−) as they share a limited resource.', 'Competition is a −/− interaction because each species reduces the resource available to the other. Mutualism is +/+, while predation and parasitism are +/− interactions benefitting one partner.', '{"a": "Mutualism benefits both partners.", "c": "The predator benefits.", "d": "The parasite benefits."}'::jsonb, 'Competition (−/−), mutualism (+/+), predation & parasitism (+/−), commensalism (+/0), amensalism (−/0).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('092e2ec0-b6e0-5232-be23-933fe85c0cee', 'neet_ug', 'Zoology', 'Reproductive Health', 'Ectopic pregnancies are referred to as :', '[{"id": "a", "text": "Pregnancies terminated due to hormonal imbalance"}, {"id": "b", "text": "Pregnancies with genetic abnormality."}, {"id": "c", "text": "Implantation of embryo at site other than uterus."}, {"id": "d", "text": "Implantation of defective embryo in the uterus"}]'::jsonb, 'c', 'Ectopic means ''out of place'': the embryo implants outside the uterus, usually in the fallopian tube.', 'Normally the blastocyst implants in the uterine endometrium. In an ectopic pregnancy implantation occurs elsewhere, most commonly in the oviduct, which cannot support the embryo and may rupture. It is a cause of infertility mentioned under reproductive health.', '{"a": "That describes a type of miscarriage, not ectopic pregnancy.", "b": "Genetic abnormality does not define site of implantation.", "d": "Implantation inside the uterus is not ectopic."}'::jsonb, 'Commonest site of ectopic pregnancy: fallopian tube (ampulla).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('4ceb9c57-201c-5155-b1c8-37a4c9906b57', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Cellular organelles with membranes are :', '[{"id": "a", "text": "Lysosomes, Golgi apparatus and mitochondria"}, {"id": "b", "text": "Nuclei, ribosomes and mitochondria"}, {"id": "c", "text": "Chromosomes, ribosomes and endoplasmic reticulum"}, {"id": "d", "text": "Endoplasmic reticulum, ribosomes and nuclei"}]'::jsonb, 'a', 'Lysosomes, Golgi bodies and mitochondria are all membrane-bound; every other option includes ribosomes.', 'Lysosomes and Golgi cisternae are single-membrane organelles and mitochondria are double-membrane organelles. Options (2), (3) and (4) each contain ribosomes, which lack a membrane (chromosomes too are non-membranous).', '{"b": "Ribosomes are non-membranous.", "c": "Chromosomes and ribosomes have no membranes.", "d": "Ribosomes have no membrane."}'::jsonb, 'Membrane-less cell components: ribosomes, centrosome, chromosomes.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('7d3206a4-abdb-5bfd-a3c2-d8f7373a3bf9', 'neet_ug', 'Botany', 'Biological Classification', 'Cell wall is absent in :', '[{"id": "a", "text": "Nostoc"}, {"id": "b", "text": "Aspergillus"}, {"id": "c", "text": "Funaria"}, {"id": "d", "text": "Mycoplasma"}]'::jsonb, 'd', 'Mycoplasma is the wall-less, smallest known living cell.', 'Mycoplasma lacks a cell wall, which makes it pleomorphic and resistant to penicillin. Nostoc (cyanobacterium) has a peptidoglycan wall, Aspergillus a chitin wall and Funaria a cellulose wall.', '{"a": "Nostoc has a bacterial cell wall with a mucilage sheath.", "b": "Fungal walls contain chitin.", "c": "Moss cells have cellulose walls."}'::jsonb, 'Mycoplasma: no cell wall, smallest cell, can survive without oxygen.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('055d70a6-3dcc-5a89-907e-54ecab804945', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'The term "linkage" was coined by :', '[{"id": "a", "text": "W.Sutton"}, {"id": "b", "text": "T.H. Morgan"}, {"id": "c", "text": "T.Boveri"}, {"id": "d", "text": "G.Mendel"}]'::jsonb, 'b', 'Morgan, working on Drosophila, coined ''linkage'' for the physical association of genes on a chromosome.', 'T.H. Morgan''s dihybrid crosses in Drosophila showed that some genes did not assort independently; he called this physical association linkage and distinguished parental from recombinant types. Sutton and Boveri proposed the chromosomal theory, and Mendel described independent assortment.', '{"a": "Sutton co-proposed the chromosomal theory of inheritance.", "c": "Boveri co-proposed the chromosomal theory.", "d": "Mendel did not know of linkage."}'::jsonb, 'Morgan coined linkage; Sturtevant used recombination frequency to map genes.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('67b0b1a8-505e-5bc3-931c-cbef1866ab8e', 'neet_ug', 'Botany', 'Biomolecules', 'Which of the following biomolecules does have a phosphodiester bond ?', '[{"id": "a", "text": "Nucleic acids in a nucleotide"}, {"id": "b", "text": "Fatty acids in a diglyceride"}, {"id": "c", "text": "Monosaccharides in a polysaccharide"}, {"id": "d", "text": "Amino acids in a polypeptide"}]'::jsonb, 'a', 'Nucleotides in nucleic acids are joined by 3′–5′ phosphodiester bonds.', 'In DNA and RNA the phosphate links the 3′-C of one sugar to the 5′-C of the next, forming a phosphodiester bond. Fatty acids in glycerides are joined by ester bonds, monosaccharides by glycosidic bonds and amino acids by peptide bonds.', '{"b": "Glycerides have ester bonds.", "c": "Polysaccharides have glycosidic bonds.", "d": "Polypeptides have peptide bonds."}'::jsonb, 'Peptide (proteins), glycosidic (carbohydrates), ester (lipids), phosphodiester (nucleic acids).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('924c3a51-83a2-5afc-946a-dc0d7fd1a428', 'neet_ug', 'Zoology', 'Animal Kingdom', 'The primary dentition in human differs from permanent dentition in not having one of the following type of teeth :', '[{"id": "a", "text": "Incisors"}, {"id": "b", "text": "Canine"}, {"id": "c", "text": "Premolars"}, {"id": "d", "text": "Molars"}]'::jsonb, 'c', 'Milk dentition (2102/2102, 20 teeth) has no premolars.', 'Humans are diphyodont. The deciduous set has 20 teeth: incisors, canines and molars in each quadrant (2-1-0-2), with no premolars. The permanent set of 32 (2-1-2-3) adds premolars and third molars.', '{"a": "Milk teeth include incisors.", "b": "Milk teeth include canines.", "d": "Milk teeth include two molars per quadrant."}'::jsonb, 'Permanent dental formula 2123/2123; premolars and third molars are absent in milk teeth.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('7210ee87-6df1-5ec8-9512-5f45ee0c3c01', 'neet_ug', 'Botany', 'Biotechnology: Principles and Processes', 'A protoplast is a cell :', '[{"id": "a", "text": "without cell wall"}, {"id": "b", "text": "without plasma membrane"}, {"id": "c", "text": "without nucleus"}, {"id": "d", "text": "undergoing division"}]'::jsonb, 'a', 'A protoplast is the living plant cell left after its cell wall is removed.', 'Protoplast = plasma membrane plus everything inside it. Enzymatic removal of the wall (with cellulase and pectinase) yields naked protoplasts used in somatic hybridisation and gene transfer.', '{"b": "The plasma membrane is retained in a protoplast.", "c": "The nucleus is part of the protoplast.", "d": "Division is unrelated to the definition."}'::jsonb, 'Protoplast fusion of tomato and potato gave the pomato (somatic hybrid).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('09a6b802-80fb-5a25-b0a4-749fc02fc886', 'neet_ug', 'Botany', 'Biological Classification', 'In which group of organisms the cells walls form two thin overlapping shells which fit together ?', '[{"id": "a", "text": "Slime moulds"}, {"id": "b", "text": "Chrysophytes"}, {"id": "c", "text": "Euglenoids"}, {"id": "d", "text": "Dinoflagellates"}]'::jsonb, 'b', 'Diatoms (chrysophytes) have siliceous walls in two overlapping halves like a soap box.', 'In diatoms the cell wall is made of two thin, overlapping shells (frustules) impregnated with silica, fitting together like a soap box; their deposits form diatomaceous earth. Dinoflagellates have cellulose plates, euglenoids a protein pellicle and slime moulds lack a wall in the vegetative stage.', '{"a": "Slime moulds form a wall-less plasmodium.", "c": "Euglenoids have a flexible pellicle, no wall.", "d": "Dinoflagellates have stiff cellulose plates, not two overlapping shells."}'::jsonb, 'Diatoms: silica walls, ''chief producers'' of oceans; diatomaceous earth.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('b1e11274-7e14-5ff3-b866-7ebe3fb3f700', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'The DNA molecules to which the gene of interest is integrated for cloning is called :', '[{"id": "a", "text": "Carrier"}, {"id": "b", "text": "Transformer"}, {"id": "c", "text": "Vector"}, {"id": "d", "text": "Template"}]'::jsonb, 'c', 'A cloning vector (plasmid or phage) carries the inserted gene into the host and replicates it.', 'The foreign gene is ligated into a vector DNA that has an ori, selectable marker and cloning sites. The recombinant vector is introduced into the host, where it replicates and produces many copies of the gene.', '{"a": "''Carrier'' is not the technical term.", "b": "Transformation is the process; there is no ''transformer'' DNA.", "d": "A template guides replication or transcription, not cloning."}'::jsonb, 'Vector features: ori, selectable marker, unique cloning (restriction) sites.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('d7d6b69b-0b96-5bcc-83ae-82f144ce2f8d', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Male gametophyte in angiosperms produces :', '[{"id": "a", "text": "Three sperms"}, {"id": "b", "text": "Two sperms and a vegetative cell"}, {"id": "c", "text": "Single sperm and a vegetative cell"}, {"id": "d", "text": "Single sperm and two vegetative cells"}]'::jsonb, 'b', 'The mature pollen grain has a vegetative (tube) cell and a generative cell that divides into two male gametes.', 'Pollen grains are shed at the 2-celled or 3-celled stage. The generative cell divides mitotically to give two sperm cells, while the vegetative cell forms the pollen tube. One sperm fuses with the egg and the other with the polar nuclei (double fertilisation).', '{"a": "Only two male gametes are formed.", "c": "The generative cell yields two sperms, not one.", "d": "There is only one vegetative cell."}'::jsonb, 'Angiosperm male gametophyte: 1 vegetative cell + 2 male gametes.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('09dd6e86-ec1f-501a-ab60-6e6850093216', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Coconut water from a tender coconut is :', '[{"id": "a", "text": "Degenerated nucellus"}, {"id": "b", "text": "Immature embryo"}, {"id": "c", "text": "Free nuclear endosperm"}, {"id": "d", "text": "Innermost layers of the seed coat"}]'::jsonb, 'c', 'Tender coconut water is free-nuclear endosperm, while the white kernel is cellular endosperm.', 'The primary endosperm nucleus divides repeatedly without wall formation, giving free-nuclear endosperm. In coconut this liquid stage persists as coconut water, surrounded by the later-formed cellular endosperm (the kernel).', '{"a": "Remnant nucellus is perisperm, as in black pepper.", "b": "The embryo is a small solid structure.", "d": "The seed coat is not liquid."}'::jsonb, 'Coconut: water = free-nuclear endosperm; meat = cellular endosperm.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('99ab2a63-5924-5bd3-8a57-d4bb24d29830', 'neet_ug', 'Botany', 'Biodiversity and Conservation', 'The species confined to a particular region and not found elsewhere is termed as :', '[{"id": "a", "text": "Rare"}, {"id": "b", "text": "Keystone"}, {"id": "c", "text": "Alien"}, {"id": "d", "text": "Endemic"}]'::jsonb, 'd', 'Endemic species are restricted to a single region.', 'Endemism means a species occurs naturally only in one geographic area, which is a key criterion for identifying biodiversity hotspots. Keystone species have disproportionate ecological impact, alien species are introduced, and rare species are simply few in number.', '{"a": "Rare refers to low abundance, not restricted range.", "b": "Keystone refers to ecological role.", "c": "Alien species are introduced from elsewhere."}'::jsonb, 'Hotspots are chosen for high endemism and high species richness.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('e4fc9d10-1aed-51b1-8bef-4f618c1f8637', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Metagenesis refers to :', '[{"id": "a", "text": "Presence of a segmented body and parthenogenetic mode of reproduction"}, {"id": "b", "text": "Presence of different morphic forms"}, {"id": "c", "text": "Alternation of generation between asexual and sexual phases of an organism"}, {"id": "d", "text": "Occurrence of a drastic change in form during post-embryonic development"}]'::jsonb, 'c', 'In cnidarians like Obelia, asexual polyps and sexual medusae alternate: metagenesis.', 'Polyps produce medusae asexually by budding, and medusae form polyps via sexual reproduction (gametes, zygote, larva). This alternation of asexual and sexual generations is called metagenesis. A drastic post-embryonic change in form is metamorphosis, and different forms in one species is polymorphism.', '{"a": "Segmentation and parthenogenesis are unrelated to metagenesis.", "b": "That is polymorphism.", "d": "That is metamorphosis."}'::jsonb, 'Obelia shows metagenesis: polyp (asexual) ⇌ medusa (sexual).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('ae580572-d122-5473-a437-5c66223881a6', 'neet_ug', 'Zoology', 'Structural Organisation in Animals', 'The function of the gap junction is to :', '[{"id": "a", "text": "stop substance from leaking across a tissue"}, {"id": "b", "text": "performing cementing to keep neighbouring cells together"}, {"id": "c", "text": "Facilitate communication between adjoining cells by connecting the cytoplasm for rapid transfer of ions, small molecules and some large molecules"}, {"id": "d", "text": "separate two cells from each other."}]'::jsonb, 'c', 'Gap junctions are cytoplasmic channels that let ions and small molecules pass directly between neighbouring cells.', 'NCERT lists three cell junctions in epithelia: tight junctions prevent leakage across the tissue, adhering junctions cement cells together, and gap junctions connect the cytoplasm of adjoining cells for rapid transfer of ions, small molecules and sometimes big molecules.', '{"a": "That is the role of tight junctions.", "b": "That is the role of adhering junctions (desmosomes).", "d": "No junction functions to separate cells."}'::jsonb, 'Tight = seal; adhering = cement; gap = communication.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('cf10a2cc-70b3-5c64-8f83-23ca4e0c2807', 'neet_ug', 'Zoology', 'Microbes in Human Welfare', 'Match the following list of microbes and their importance :
(a) Saccharomyces cerevisiae | (i) Production of immunosuppressive agents
(b) Monascus purpureus | (ii) Ripening of Swiss cheese
(c) Trichoderma polysporum | (iii) Commercial production of ethanol
(d) Propionibacterium sharmanii | (iv) Production of blood cholesterol lowering agents', '[{"id": "a", "text": "(a)-(iii), (b)-(i), (c)-(iv), (d)-(ii)"}, {"id": "b", "text": "(a)-(iii), (b)-(iv), (c)-(i), (d)-(ii)"}, {"id": "c", "text": "(a)-(iv), (b)-(iii), (c)-(ii), (d)-(i)"}, {"id": "d", "text": "(a)-(iv), (b)-(ii), (c)-(i), (d)-(iii)"}]'::jsonb, 'b', 'Yeast–ethanol, Monascus–statins, Trichoderma–cyclosporin A, Propionibacterium–Swiss cheese.', 'Saccharomyces cerevisiae ferments sugars for industrial ethanol. Monascus purpureus yields statins, which lower blood cholesterol. Trichoderma polysporum produces cyclosporin A, an immunosuppressant for organ transplants. Propionibacterium sharmanii produces CO₂ that forms the large holes of Swiss cheese.', '{"a": "Swaps Monascus and Trichoderma products.", "c": "Yeast does not make statins, and Propionibacterium does not make immunosuppressants.", "d": "Yeast does not make statins and Monascus does not ripen cheese."}'::jsonb, 'Cyclosporin A – Trichoderma polysporum; statins – Monascus purpureus.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('41a16d39-9f64-5da4-8775-1c51c990cbb1', 'neet_ug', 'Botany', 'Cell Cycle and Cell Division', 'Arrange the following events of meiosis in correct sequence :
(a) Crossing over
(b) Synapsis
(c) Terminalisation of chiasmata
(d) Disappearance of nucleolus', '[{"id": "a", "text": "(b), (c), (d), (a)"}, {"id": "b", "text": "(b), (a), (d), (c)"}, {"id": "c", "text": "(b), (a), (c), (d)"}, {"id": "d", "text": "(a), (b), (c), (d)"}]'::jsonb, 'c', 'Synapsis (zygotene) → crossing over (pachytene) → terminalisation (diakinesis) → nucleolus disappears (end of diakinesis).', 'Homologues pair during zygotene, crossing over occurs at pachytene, and chiasmata form at diplotene and terminalise during diakinesis. By the end of diakinesis the nucleolus disappears and the nuclear envelope breaks down, marking the transition to metaphase I.', '{"a": "Crossing over cannot come after terminalisation.", "b": "Terminalisation precedes the final disappearance of the nucleolus.", "d": "Crossing over requires prior synapsis."}'::jsonb, 'Prophase I: leptotene, zygotene (synapsis), pachytene (crossing over), diplotene (chiasmata), diakinesis (terminalisation).', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('59a0aca9-bf94-56ab-a764-b58b4a028e0e', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'The cutting of DNA at specific locations became possible with the discovery of :', '[{"id": "a", "text": "Ligases"}, {"id": "b", "text": "Restriction enzymes"}, {"id": "c", "text": "Probes"}, {"id": "d", "text": "Selectable markers"}]'::jsonb, 'b', 'Restriction endonucleases cut DNA at specific recognition sequences (''molecular scissors'').', 'Restriction enzymes recognise specific palindromic sequences and cut both strands at defined positions, which made recombinant DNA technology possible. Ligases join DNA, probes detect sequences and selectable markers identify transformants.', '{"a": "Ligases join DNA fragments.", "c": "Probes are labelled sequences for detection.", "d": "Markers help select transformed cells."}'::jsonb, 'First restriction endonuclease characterised: Hind II.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('fce0ae4e-ef80-5a14-a03f-93b731dc0dfa', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Grafted kidney may be rejected in a patient due to', '[{"id": "a", "text": "Innate immune response"}, {"id": "b", "text": "Humoral immune response"}, {"id": "c", "text": "Cell-mediated immune response"}, {"id": "d", "text": "Passive immune response"}]'::jsonb, 'c', 'Graft rejection is mediated by T lymphocytes, i.e. cell-mediated immunity.', 'The body distinguishes ''self'' from ''non-self'' tissue, and T cells attack the foreign graft. This T-cell (cell-mediated) response is why tissue matching and immunosuppressants are needed after transplantation.', '{"a": "Innate immunity is non-specific and is not the main cause of graft rejection.", "b": "Antibody-based humoral immunity is not the principal mechanism in NCERT.", "d": "Passive immunity uses ready-made antibodies and does not reject grafts."}'::jsonb, 'Cell-mediated immunity (T cells) is responsible for graft rejection.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('b99bbfe3-6bf4-594d-a1ba-81886989d307', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Filiform apparatus is characteristic feature of :', '[{"id": "a", "text": "Synergids"}, {"id": "b", "text": "Generative cell"}, {"id": "c", "text": "Nucellar embryo"}, {"id": "d", "text": "Aleurone cell"}]'::jsonb, 'a', 'The synergids carry finger-like thickenings, the filiform apparatus, at their micropylar tips.', 'The two synergids beside the egg cell have cellular thickenings at the micropylar end called the filiform apparatus. It guides the pollen tube into the synergid during fertilisation.', '{"b": "The generative cell is in the pollen grain.", "c": "A nucellar embryo is an apomictic embryo.", "d": "Aleurone cells are protein-rich endosperm cells."}'::jsonb, 'Filiform apparatus guides pollen tube entry into the embryo sac.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('025735c6-1f81-543a-8063-937263837147', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'The wheat grain has an embryo with one large, shield-shaped cotyledon known as :', '[{"id": "a", "text": "Coleoptile"}, {"id": "b", "text": "Epiblast"}, {"id": "c", "text": "Coleorrhiza"}, {"id": "d", "text": "Scutellum"}]'::jsonb, 'd', 'In grasses the single shield-shaped cotyledon is the scutellum.', 'Monocot embryos of the grass family have one cotyledon called the scutellum, situated laterally on the embryonal axis. The plumule is sheathed by the coleoptile and the radicle by the coleorrhiza; the epiblast is a small outgrowth opposite the scutellum.', '{"a": "Coleoptile covers the plumule.", "b": "Epiblast is a rudimentary second cotyledon-like outgrowth.", "c": "Coleorrhiza covers the radicle."}'::jsonb, 'Grass embryo: scutellum (cotyledon), coleoptile (plumule sheath), coleorrhiza (radicle sheath).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('82d38108-be22-5243-995a-14330467790e', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'Among china rose, mustard, brinjal, potato, guava, cucumber, onion and tulip, how many plants have superior ovary?', '[{"id": "a", "text": "Four"}, {"id": "b", "text": "Five"}, {"id": "c", "text": "Six"}, {"id": "d", "text": "Three"}]'::jsonb, 'c', 'All except guava and cucumber (epigynous, inferior ovary) are hypogynous: six.', 'China rose (Malvaceae), mustard (Brassicaceae), brinjal and potato (Solanaceae), onion and tulip (Liliaceae) have hypogynous flowers with a superior ovary. Guava and cucumber have epigynous flowers with an inferior ovary. So 6 of the 8 have superior ovaries.', '{"a": "Undercounts the hypogynous plants.", "b": "Undercounts; only guava and cucumber are inferior.", "d": "Far too few."}'::jsonb, 'Epigynous (inferior ovary): guava, cucumber, sunflower ray florets.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('e3147578-ff73-52a2-873f-1f4bd55ce739', 'neet_ug', 'Zoology', 'Locomotion and Movement', 'Which of the following is not a function of the skeletal system?', '[{"id": "a", "text": "Locomotion"}, {"id": "b", "text": "Production of erythrocytes"}, {"id": "c", "text": "Storage of minerals"}, {"id": "d", "text": "Production of body heat"}]'::jsonb, 'd', 'Body heat comes mainly from muscle and metabolic activity, not from the skeleton.', 'The skeleton provides support and levers for locomotion, red bone marrow produces blood cells, and bone stores calcium and phosphate. Heat production is a function of muscles (and metabolism), not bones.', '{"a": "Bones act as levers for muscles during locomotion.", "b": "Red bone marrow is the site of erythropoiesis.", "c": "Bone stores Ca and P."}'::jsonb, 'Skeleton: support, protection, movement, haemopoiesis, mineral storage.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('b3f343ec-4bca-5c02-9217-e509eac557b5', 'neet_ug', 'Zoology', 'Biotechnology and its Applications', 'Golden rice is a genetically modified crop plant where the incorporated gene is meant for biosynthesis of :', '[{"id": "a", "text": "Vitamin A"}, {"id": "b", "text": "Vitamin B"}, {"id": "c", "text": "Vitamin C"}, {"id": "d", "text": "Omega 3"}]'::jsonb, 'a', 'Golden rice carries genes for β-carotene, the provitamin A pigment that gives it a golden colour.', 'Genes for the β-carotene pathway were introduced into rice endosperm so the grain synthesises provitamin A. It was developed to combat vitamin A deficiency (night blindness) in rice-eating populations.', '{"b": "No B-vitamin pathway was engineered.", "c": "Vitamin C was not targeted.", "d": "Omega-3 fatty acids were not the target."}'::jsonb, 'Golden rice = β-carotene (provitamin A) enriched GM rice.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('dd7dd104-e0a6-590a-9698-80b1fd0955b0', 'neet_ug', 'Botany', 'Biological Classification', 'Chromatophores take part in :', '[{"id": "a", "text": "Respiration"}, {"id": "b", "text": "Photosynthesis"}, {"id": "c", "text": "Growth"}, {"id": "d", "text": "Movement"}]'::jsonb, 'b', 'In photosynthetic prokaryotes, chromatophores are pigment-bearing membrane extensions that perform photosynthesis.', 'Cyanobacteria and other photosynthetic bacteria lack chloroplasts; their photosynthetic pigments sit in membranous infoldings of the cell membrane called chromatophores. These are the sites of light absorption and photosynthesis.', '{"a": "Respiration in bacteria occurs on the plasma membrane/mesosomes.", "c": "Growth is not a specific role of chromatophores.", "d": "Movement is due to flagella."}'::jsonb, 'Chromatophores: pigment-containing membrane systems of photosynthetic bacteria.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('d814eaf1-f4be-59bc-b6b1-8e4e1c112dec', 'neet_ug', 'Botany', 'Biological Classification', 'Select the wrong statement :', '[{"id": "a", "text": "Mosaic disease in tobacco and AIDS in human being are caused by viruses"}, {"id": "b", "text": "The viroids were discovered by D.J. Ivanowski"}, {"id": "c", "text": "W.M. Stanley showed that viruses could be crystallized"}, {"id": "d", "text": "The term ''contagium vivum fluidum'' was coined by M.W. Beijerinek"}]'::jsonb, 'b', 'Viroids were discovered by T.O. Diener (1971); Ivanowski studied tobacco mosaic virus.', 'Ivanowski (1892) showed that the agent of tobacco mosaic passed through bacteria-proof filters. Viroids, free infectious RNA without a protein coat, were discovered by T.O. Diener in 1971 as the cause of potato spindle tuber disease. The other statements are correct.', '{"a": "True: TMV and HIV are viruses.", "c": "True: Stanley crystallised TMV (1935).", "d": "True: Beijerinck called the filterable agent contagium vivum fluidum."}'::jsonb, 'Viroid discoverer: T.O. Diener; TMV crystallised by W.M. Stanley.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('2d1d4b17-7ff2-5ea4-9677-9f69ea6523e2', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'A pleiotropic gene :', '[{"id": "a", "text": "controls multiple traits in an individual"}, {"id": "b", "text": "is expressed only in primitive plants"}, {"id": "c", "text": "is a gene evolved during Pliocene"}, {"id": "d", "text": "controls a trait only in combination with another gene"}]'::jsonb, 'a', 'Pleiotropy: one gene affecting several phenotypic traits.', 'A pleiotropic gene has multiple phenotypic effects, usually because its product acts in a metabolic pathway affecting several characters, e.g. phenylketonuria or starch grain size and seed shape in pea. Control of a trait by several genes together is polygenic inheritance or gene interaction.', '{"b": "Pleiotropy is not restricted to primitive plants.", "c": "It has nothing to do with geological period.", "d": "That describes gene interaction / polygenic control."}'::jsonb, 'Phenylketonuria is a classic example of pleiotropy.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('883ce341-2454-5f48-96ab-fd70942765f1', 'neet_ug', 'Zoology', 'Excretory Products and their Elimination', 'Human urine is usually acidic because :', '[{"id": "a", "text": "hydrogen ions are actively secreted into the filtrate."}, {"id": "b", "text": "the sodium transporter exchanges one hydrogen ion for each sodium ion, in peritubular capillaries."}, {"id": "c", "text": "excreted plasma proteins are acidic"}, {"id": "d", "text": "potassium and sodium exchange generates acidity"}]'::jsonb, 'a', 'Tubular cells actively secrete H⁺ into the filtrate (and retain HCO₃⁻), making urine slightly acidic.', 'The PCT and DCT maintain blood pH by secreting hydrogen ions (and ammonia) into the tubular lumen while reabsorbing bicarbonate. The added H⁺ makes the final urine slightly acidic, around pH 6.', '{"b": "The exchange occurs across the tubular epithelium, not in peritubular capillaries.", "c": "Plasma proteins are not normally filtered or excreted.", "d": "K⁺–Na⁺ exchange does not account for acidity."}'::jsonb, 'Normal urine pH ≈ 6.0; H⁺ secretion and HCO₃⁻ reabsorption maintain blood pH.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('feafd7ab-9111-5b3c-9899-d20c734e6ad9', 'neet_ug', 'Botany', 'Plant Growth and Development', 'Auxin can be bioassayed by :', '[{"id": "a", "text": "Lettuce hypocotyl elongation"}, {"id": "b", "text": "Avena coleoptile curvature"}, {"id": "c", "text": "Hydroponics"}, {"id": "d", "text": "Potometer"}]'::jsonb, 'b', 'Went''s Avena curvature test measures auxin by the bending of decapitated oat coleoptiles.', 'F.W. Went placed agar blocks containing auxin asymmetrically on decapitated Avena coleoptiles; the curvature produced is proportional to auxin concentration. Lettuce hypocotyl elongation is a gibberellin bioassay, hydroponics is soil-less culture and a potometer measures transpiration.', '{"a": "Lettuce hypocotyl elongation assays gibberellins.", "c": "Hydroponics is a cultivation method.", "d": "Potometer measures water uptake/transpiration."}'::jsonb, 'Went isolated auxin from Avena coleoptile tips.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('84f9cf4c-2734-55b4-b21e-a61a27ce4745', 'neet_ug', 'Zoology', 'Animal Kingdom', 'Body having meshwork of cells, internal cavities lined with food filtering flagellated cells and indirect development are the characteristics of phylum :', '[{"id": "a", "text": "Protozoa"}, {"id": "b", "text": "Coelenterata"}, {"id": "c", "text": "Porifera"}, {"id": "d", "text": "Mollusca"}]'::jsonb, 'c', 'Sponges have a cellular-level body with canals lined by flagellated choanocytes and develop through a larva.', 'Porifera show cellular grade organisation with a loose meshwork of cells, a water canal system and spongocoel lined by choanocytes (collar cells) that filter food. Fertilisation is internal and development is indirect with a larval stage.', '{"a": "Protozoa are unicellular.", "b": "Coelenterates have cnidoblasts and tissue-level organisation.", "d": "Molluscs have organ-system level organisation."}'::jsonb, 'Choanocytes line the spongocoel and canals in sponges.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('65556eb2-793b-5b03-bd7e-5a6509d42a65', 'neet_ug', 'Zoology', 'Chemical Coordination and Integration', 'Which one of the following hormones is not involved in sugar metabolism ?', '[{"id": "a", "text": "Glucagon"}, {"id": "b", "text": "Cortisone"}, {"id": "c", "text": "Aldosterone"}, {"id": "d", "text": "Insulin"}]'::jsonb, 'c', 'Aldosterone is a mineralocorticoid regulating Na⁺, K⁺ and water, not glucose.', 'Insulin lowers and glucagon raises blood glucose, and glucocorticoids such as cortisol/cortisone stimulate gluconeogenesis. Aldosterone acts on renal tubules to reabsorb Na⁺ and water and excrete K⁺, so it does not regulate carbohydrate metabolism.', '{"a": "Glucagon promotes glycogenolysis and gluconeogenesis.", "b": "Glucocorticoids raise blood sugar via gluconeogenesis.", "d": "Insulin promotes glucose uptake and glycogenesis."}'::jsonb, 'Aldosterone = mineralocorticoid; cortisol = glucocorticoid.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('c4f587a3-7871-5d6f-9da0-04354d365dec', 'neet_ug', 'Zoology', 'Reproductive Health', 'A childless couple can be assisted to have a child through a technique called GIFT. The full form of this technique is :', '[{"id": "a", "text": "Germ cell internal fallopian transfer"}, {"id": "b", "text": "Gamete inseminated fallopian transfer"}, {"id": "c", "text": "Gamete intra fallopian transfer"}, {"id": "d", "text": "Gamete internal fertilization and transfer"}]'::jsonb, 'c', 'GIFT = Gamete Intra Fallopian Transfer: an ovum from a donor is placed in the fallopian tube of a female who cannot produce one.', 'In GIFT, gametes (an ovum collected from a donor) are transferred into the fallopian tube of a woman who cannot produce ova but can provide a suitable environment for fertilisation and development. Fertilisation then occurs in vivo.', '{"a": "Incorrect expansion.", "b": "Incorrect expansion; no insemination term is used.", "d": "Incorrect expansion."}'::jsonb, 'ART: IVF-ET, ZIFT, IUT, GIFT, ICSI, IUI.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('270e81fd-46ec-50e1-b1a3-b7aca932fe57', 'neet_ug', 'Zoology', 'Animal Kingdom', 'A jawless fish, which lays eggs in fresh water and whose ammocoetes larvae after metamorphosis return to the ocean is :', '[{"id": "a", "text": "Petromyzon"}, {"id": "b", "text": "Eptatretus"}, {"id": "c", "text": "Myxine"}, {"id": "d", "text": "Neomyxine"}]'::jsonb, 'a', 'The lamprey Petromyzon migrates to fresh water to spawn; its ammocoete larvae return to the sea after metamorphosis.', 'Cyclostomes are marine but migrate to fresh water for spawning, after which the adults die; the larvae return to the ocean after metamorphosis. Lampreys (Petromyzon) have the ammocoete larva, whereas hagfishes (Myxine, Eptatretus, Neomyxine) develop directly without a larval stage.', '{"b": "Eptatretus is a hagfish with direct development.", "c": "Myxine (hagfish) has no ammocoete larva.", "d": "Neomyxine is a hagfish with direct development."}'::jsonb, 'Cyclostomata examples: Petromyzon (lamprey), Myxine (hagfish).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('1fcfad29-fcbc-5d1d-8f98-b875e35a6370', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'The structures that help some bacteria to attach to rocks and/or host tissues are :', '[{"id": "a", "text": "Holdfast"}, {"id": "b", "text": "Rhizoids"}, {"id": "c", "text": "Fimbriae"}, {"id": "d", "text": "Mesosomes"}]'::jsonb, 'c', 'Fimbriae are small bristle-like surface fibres that help bacteria adhere to rocks or host tissue.', 'Bacterial surface structures include flagella (motility), pili (elongated tubular structures) and fimbriae, small bristle-like fibres that help some bacteria attach to rocks in streams and to host tissues. Holdfasts and rhizoids are anchoring organs of algae and bryophytes, and mesosomes are internal membrane infoldings.', '{"a": "Holdfasts anchor large algae such as kelps.", "b": "Rhizoids anchor bryophytes.", "d": "Mesosomes are internal and function in wall formation, DNA replication and respiration."}'::jsonb, 'Pili and fimbriae do not play a role in motility.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('9cd3de55-b8ae-5545-956f-f1497d00aa65', 'neet_ug', 'Zoology', 'Body Fluids and Circulation', 'If you suspect major deficiency of antibodies in a person, to which of the following would you look for confirmatory evidence?', '[{"id": "a", "text": "Serum globulins"}, {"id": "b", "text": "Fibrinogin in plasma"}, {"id": "c", "text": "Serum albumins"}, {"id": "d", "text": "Haemocytes"}]'::jsonb, 'a', 'Antibodies are immunoglobulins, i.e. part of the globulin fraction of plasma proteins.', 'Plasma proteins are fibrinogen (clotting), albumin (osmotic balance) and globulins (defence). Antibodies are gamma-globulins, so a low serum globulin level would confirm antibody deficiency.', '{"b": "Fibrinogen is involved in coagulation.", "c": "Albumin maintains colloidal osmotic pressure.", "d": "Haemocytes are blood cells of invertebrates, not antibodies."}'::jsonb, 'Globulins are primarily involved in the defence mechanisms of the body.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('a1fc2786-1323-5718-ac2b-0e6221f7d0db', 'neet_ug', 'Zoology', 'Human Reproduction', 'In human females, meiosis-II is not completed until?', '[{"id": "a", "text": "birth"}, {"id": "b", "text": "puberty"}, {"id": "c", "text": "fertilization"}, {"id": "d", "text": "uterine implantation"}]'::jsonb, 'c', 'The secondary oocyte completes meiosis II only after a sperm enters it.', 'Meiosis I is arrested in prophase I from fetal life until just before ovulation, when it completes to form a secondary oocyte. The secondary oocyte is arrested at metaphase II and completes the second meiotic division only upon sperm entry, giving the ovum and second polar body.', '{"a": "At birth the oocytes are arrested in prophase I.", "b": "Puberty resumes follicle maturation, not completion of meiosis II.", "d": "Implantation occurs days after fertilisation, when meiosis is long over."}'::jsonb, 'Sperm entry induces completion of meiosis II in the secondary oocyte.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('d8afd0fa-bbb1-5d31-b2e7-1eaf6a8ba186', 'neet_ug', 'Zoology', 'Human Reproduction', 'Which of the following layers in an antral follicle is acellular ?', '[{"id": "a", "text": "Zona pellucida"}, {"id": "b", "text": "Granulosa"}, {"id": "c", "text": "Theca interna"}, {"id": "d", "text": "Stroma"}]'::jsonb, 'a', 'The zona pellucida is a non-cellular glycoprotein coat around the oocyte.', 'The oocyte of a tertiary/Graafian follicle is surrounded by an acellular glycoprotein layer, the zona pellucida. Granulosa cells, theca interna and stroma are all cellular layers.', '{"b": "Granulosa is made of follicular cells.", "c": "Theca interna is a cellular layer that secretes oestrogen precursors.", "d": "Stroma is ovarian connective tissue with cells."}'::jsonb, 'Zona pellucida blocks polyspermy after fertilisation.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('00ac5102-0508-545a-b327-4462245684e1', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'In his classic experiments on pea plants, Mendel did not use :', '[{"id": "a", "text": "Flower position"}, {"id": "b", "text": "Seed colour"}, {"id": "c", "text": "Pod length"}, {"id": "d", "text": "Seed shape"}]'::jsonb, 'c', 'Mendel studied pod shape and pod colour, not pod length.', 'Mendel''s seven characters were stem height, flower colour, flower position, pod shape, pod colour, seed shape and seed colour. Pod length was not among them.', '{"a": "Flower position (axial/terminal) was one of the seven traits.", "b": "Seed colour (yellow/green) was studied.", "d": "Seed shape (round/wrinkled) was studied."}'::jsonb, 'Mendel''s seven traits: height, flower colour, flower position, pod shape, pod colour, seed shape, seed colour.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('a0e0dd21-7da4-5913-8110-64a118cef5b1', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'Which one of the following fruits is parthenocarpic?', '[{"id": "a", "text": "Banana"}, {"id": "b", "text": "Brinjal"}, {"id": "c", "text": "Apple"}, {"id": "d", "text": "Jackfruit"}]'::jsonb, 'a', 'Banana develops fruit without fertilisation, so it is seedless and parthenocarpic.', 'Parthenocarpic fruits develop from the ovary without fertilisation and are seedless; banana is the classic example. Brinjal, apple and jackfruit normally develop after fertilisation and contain seeds.', '{"b": "Brinjal is a seeded true fruit.", "c": "Apple is a seeded false fruit.", "d": "Jackfruit is a seeded composite fruit."}'::jsonb, 'Parthenocarpy can be induced by auxins/growth hormones.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('bc4d4088-8c71-59d4-bf01-a9b9527e8c56', 'neet_ug', 'Botany', 'Sexual Reproduction in Flowering Plants', 'In angiosperms, microsporogenesis and megasporogenesis :', '[{"id": "a", "text": "occur in ovule"}, {"id": "b", "text": "occur in anther"}, {"id": "c", "text": "form gametes without furthers divisions"}, {"id": "d", "text": "involve meiosis"}]'::jsonb, 'd', 'Both processes form haploid spores from diploid mother cells by meiosis.', 'Microspore mother cells in the anther and the megaspore mother cell in the ovule both undergo meiosis to form haploid microspores and megaspores. Microsporogenesis occurs in the anther and megasporogenesis in the ovule, and the spores must divide further (mitosis) to form gametophytes and gametes.', '{"a": "Only megasporogenesis occurs in the ovule.", "b": "Only microsporogenesis occurs in the anther.", "c": "Spores undergo mitosis to form gametophytes before gametes form."}'::jsonb, 'Meiosis in MMC and PMC gives haploid spores; gametophytes form by mitosis.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('0f620f2a-6014-5374-b787-4446df68c85a', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'A gene showing codominance has :', '[{"id": "a", "text": "both alleles independently expressed in the heterozygote"}, {"id": "b", "text": "one allele dominant on the other"}, {"id": "c", "text": "alleles tightly linked on the same chromosome"}, {"id": "d", "text": "alleles that are recessive to each other"}]'::jsonb, 'a', 'In codominance both alleles are fully expressed together in the heterozygote, e.g. Iᴬ Iᴮ gives AB blood group.', 'In codominance the F₁ resembles both parents because each allele produces its product independently. In ABO blood groups, Iᴬ and Iᴮ both make their respective sugars in an AB individual.', '{"b": "That is complete dominance.", "c": "Linkage concerns different genes, not alleles of one gene.", "d": "Alleles recessive to each other is not a defined inheritance pattern."}'::jsonb, 'ABO blood group shows codominance (Iᴬ, Iᴮ) and multiple allelism.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('b878b36d-1158-5c8e-a7ec-3de63ff740ab', 'neet_ug', 'Zoology', 'Biomolecules', 'The chitinous exoskeleton of arthropods is formed by the polymerisation of :', '[{"id": "a", "text": "lipoglycans"}, {"id": "b", "text": "keratin sulphate and chondroitin sulphate"}, {"id": "c", "text": "D-glucosamine"}, {"id": "d", "text": "N-acetyl glucosamine"}]'::jsonb, 'd', 'Chitin is a homopolymer of N-acetylglucosamine.', 'Chitin is a complex polysaccharide in which N-acetyl-D-glucosamine units are joined by β-1,4 glycosidic bonds. It forms the arthropod exoskeleton and fungal cell walls.', '{"a": "Lipoglycans are not the monomer of chitin.", "b": "These are glycosaminoglycans of connective tissue.", "c": "Chitin''s monomer is the acetylated form, not free glucosamine."}'::jsonb, 'Chitin: N-acetylglucosamine polymer; also in fungal walls.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('0821d138-1c16-5fc8-8ed8-437f10409545', 'neet_ug', 'Botany', 'Biological Classification', 'The imperfect fungi which are decomposers of litter and help in mineral cycling belong to :', '[{"id": "a", "text": "Ascomycetes"}, {"id": "b", "text": "Deuteromycetes"}, {"id": "c", "text": "Basidiomycetes"}, {"id": "d", "text": "Phycomycetes"}]'::jsonb, 'b', 'Deuteromycetes are the ''imperfect fungi'' because only their asexual phase is known; many are litter decomposers.', 'Fungi whose sexual stage is unknown are placed in Deuteromycetes (imperfect fungi). Many members are saprophytes or parasites, and a large number are decomposers of litter that aid mineral cycling. Examples are Alternaria, Colletotrichum and Trichoderma.', '{"a": "Ascomycetes have known sexual ascospores.", "c": "Basidiomycetes have basidiospores.", "d": "Phycomycetes have zygospores/oospores."}'::jsonb, 'Deuteromycetes: asexual conidia only; e.g. Alternaria, Trichoderma.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('e14124d3-0913-5497-b0a5-9ad44c146ce1', 'neet_ug', 'Zoology', 'Evolution', 'The wings of a bird and the wings of an insect are :', '[{"id": "a", "text": "homologous structures and represent convergent evolution"}, {"id": "b", "text": "homologous structures and represent divergent evolution"}, {"id": "c", "text": "analogous structures and represent convergent evolution"}, {"id": "d", "text": "phylogenetic structures and represent divergent evolution"}]'::jsonb, 'c', 'Bird and insect wings share function but not origin: analogous, from convergent evolution.', 'Bird wings are modified forelimbs with bones, while insect wings are cuticular outgrowths. Their similar flight function arose independently in unrelated lines, making them analogous structures produced by convergent evolution.', '{"a": "They are not homologous, as their anatomy and origin differ.", "b": "Homologous organs indicate divergent evolution, but these are not homologous.", "d": "''Phylogenetic structures'' is not the correct term."}'::jsonb, 'Analogous organs → convergent evolution; homologous organs → divergent evolution.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('0fa5f1c7-8ad0-5f70-881d-a33e86621e5d', 'neet_ug', 'Botany', 'Morphology of Flowering Plants', 'Flowers are unisexual in :', '[{"id": "a", "text": "Onion"}, {"id": "b", "text": "Pea"}, {"id": "c", "text": "Cucumber"}, {"id": "d", "text": "China rose"}]'::jsonb, 'c', 'Cucumber is monoecious, bearing separate male and female flowers.', 'Cucurbits like cucumber produce unisexual staminate and pistillate flowers on the same plant. Onion, pea and China rose have bisexual flowers.', '{"a": "Onion flowers are bisexual.", "b": "Pea flowers are bisexual.", "d": "China rose flowers are bisexual."}'::jsonb, 'Cucurbits and maize are monoecious; papaya and date palm are dioecious.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('6872b54f-9c58-59b6-9977-ff6b50c7ca9b', 'neet_ug', 'Botany', 'Cell: The Unit of Life', 'Match the columns and identify the correct option:
Column-I | Column-II
(a) Thylakoids | (i) Disc-shaped sacs in Golgi apparatus
(b) Cristae | (ii) Condensed structure of DNA
(c) Cisternae | (iii) Flat membranous sacs in stroma
(d) Chromatin | (iv) Infoldings in mitochondria', '[{"id": "a", "text": "(a)-(iii), (b)-(iv), (c)-(ii), (d)-(i)"}, {"id": "b", "text": "(a)-(iv), (b)-(iii), (c)-(i), (d)-(ii)"}, {"id": "c", "text": "(a)-(iii), (b)-(iv), (c)-(i), (d)-(ii)"}, {"id": "d", "text": "(a)-(iii), (b)-(i), (c)-(iv), (d)-(ii)"}]'::jsonb, 'c', 'Thylakoids are stromal sacs, cristae are mitochondrial infoldings, cisternae are Golgi discs and chromatin is condensed DNA.', 'Thylakoids are flattened membranous sacs lying in the chloroplast stroma. Cristae are the infoldings of the inner mitochondrial membrane. Golgi cisternae are flat disc-shaped sacs, and chromatin is DNA packed with histones. This gives a-iii, b-iv, c-i, d-ii.', '{"a": "Gives cisternae to DNA and chromatin to Golgi, which is reversed.", "b": "Swaps thylakoids and cristae.", "d": "Calls cristae Golgi sacs and cisternae mitochondrial folds."}'::jsonb, 'Inner mitochondrial membrane folds into cristae; grana are stacks of thylakoids.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('985515fa-90cd-5a43-a2e2-c5bf21f20ea4', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Identify the correct order of organisation of genetic material from largest to smallest :', '[{"id": "a", "text": "Chromosome, genome, nucleotide, gene"}, {"id": "b", "text": "Chromosome, gene, genome, nucleotide"}, {"id": "c", "text": "Genome, chromosomes, nucleotide, gene"}, {"id": "d", "text": "Genome, chromosome, gene, nucleotide"}]'::jsonb, 'd', 'Genome > chromosome > gene > nucleotide.', 'The genome is the full haploid set of DNA and is divided into chromosomes. Each chromosome carries many genes. Each gene is a stretch of DNA built from nucleotides, the smallest unit here.', '{"a": "A chromosome is part of the genome, not larger, and a gene is larger than a nucleotide.", "b": "The genome cannot be smaller than a gene or a chromosome.", "c": "A nucleotide is smaller than a gene."}'::jsonb, 'Human haploid genome has about 3.1 × 10⁹ bp spread over 23 chromosomes.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('c58d5968-b8ba-57af-a13b-5825f80c7909', 'neet_ug', 'Zoology', 'Chemical Coordination and Integration', 'Which one of the following hormones though synthesised elsewhere, is stored and released by the master gland ?', '[{"id": "a", "text": "Melanocyte stimulating hormone"}, {"id": "b", "text": "Antidiuretic hormone"}, {"id": "c", "text": "Luteinizing hormone"}, {"id": "d", "text": "Prolactin"}]'::jsonb, 'b', 'ADH is made in the hypothalamus and stored and released by the posterior pituitary.', 'The neurohypophysis does not synthesise hormones. Oxytocin and vasopressin (ADH) are made by hypothalamic neurons, travel down their axons, and are stored and released from the posterior pituitary. MSH, LH and prolactin are made by the pituitary itself.', '{"a": "MSH is secreted by the pars intermedia of the pituitary itself.", "c": "LH is synthesised by the anterior pituitary.", "d": "Prolactin is synthesised by the anterior pituitary."}'::jsonb, 'Posterior pituitary stores and releases oxytocin and vasopressin made in the hypothalamus.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('0ef5993d-c428-5b3a-87e9-ff4e2c0a53e3', 'neet_ug', 'Zoology', 'Locomotion and Movement', 'Which of the following joints would allow no movement ?', '[{"id": "a", "text": "Ball and Socket joint"}, {"id": "b", "text": "Fibrous joint"}, {"id": "c", "text": "Cartilaginous joint"}, {"id": "d", "text": "Synovial joint"}]'::jsonb, 'b', 'Fibrous joints, such as skull sutures, allow no movement.', 'In fibrous joints the bones are held together by dense fibrous connective tissue, as in the sutures of the skull, so no movement is possible. Cartilaginous joints allow limited movement, and synovial joints, including ball and socket joints, allow considerable movement.', '{"a": "Ball and socket joints, such as the shoulder, allow movement in many directions.", "c": "Cartilaginous joints, such as between vertebrae, allow limited movement.", "d": "Synovial joints have a fluid-filled cavity and are freely movable."}'::jsonb, 'Fibrous = immovable (sutures); cartilaginous = slightly movable (vertebrae); synovial = freely movable.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('820f1c3c-7f61-5834-959d-2eb421733bd7', 'neet_ug', 'Zoology', 'Body Fluids and Circulation', 'Doctors use stethoscope to hear the sound produced during each cardiac cycle. The second sound is heard when :', '[{"id": "a", "text": "AV node receives signal from SA node"}, {"id": "b", "text": "AV valves open up"}, {"id": "c", "text": "Ventricular walls vibrate due to gushing of blood from atria"}, {"id": "d", "text": "Semilunar valves close down after the blood flows into vessels from ventricles"}]'::jsonb, 'd', '''Dub'', the second heart sound, comes from the closure of the semilunar valves.', 'The first sound (''lub'') is made when the AV valves close at the start of ventricular systole. When the ventricles relax after pushing blood into the aorta and pulmonary artery, the semilunar valves snap shut and produce the second sound (''dub'').', '{"a": "Conduction of the impulse makes no audible sound.", "b": "Opening of the valves is silent; the sounds come from valve closure.", "c": "This describes ventricular filling, not the second sound."}'::jsonb, 'Lub = AV valve closure; dub = semilunar valve closure.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('46e29d97-15b5-571b-b1b7-a8a3edb33e17', 'neet_ug', 'Botany', 'Principles of Inheritance and Variation', 'In the following human pedigree, the filled symbols represent the affected individuals. Identify the type of given pedigree.', '[{"id": "a", "text": "X-linked dominant"}, {"id": "b", "text": "Autosomal dominant"}, {"id": "c", "text": "X-linked recessive"}, {"id": "d", "text": "Autosomal recessive"}]'::jsonb, 'd', 'Unaffected parents have affected children, and an affected mother has an unaffected son, so the trait is autosomal recessive.', 'In generations II and III, unaffected parents produce affected sons, so the trait is recessive and both dominant options are ruled out. An affected female in generation II has an unaffected son. Under X-linked recessive inheritance every son of an affected mother would be affected, so the trait must be autosomal recessive.', '{"a": "A dominant trait cannot appear in children of two unaffected parents.", "b": "Unaffected × unaffected parents producing affected children rules out dominance.", "c": "An affected mother with a normal son rules out X-linked recessive."}'::jsonb, 'Normal parents with an affected child means recessive; an affected mother with a normal son rules out X-linked recessive.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', '/pyq/ug/2015/123.webp'),
('04d6cd96-7cab-5d17-befe-8ce10c00636d', 'neet_ug', 'Zoology', 'Breathing and Exchange of Gases', 'Name the pulmonary disease in which alveolar surface area involved in gas exchange is drastically reduced due to damage in the alveolar walls :', '[{"id": "a", "text": "Asthma"}, {"id": "b", "text": "Pleurisy"}, {"id": "c", "text": "Emphysema"}, {"id": "d", "text": "Pneumonia"}]'::jsonb, 'c', 'Emphysema destroys alveolar walls and so reduces the gas-exchange surface.', 'In emphysema, mainly caused by cigarette smoking, the alveolar walls break down and many alveoli merge into fewer large sacs. This sharply cuts the respiratory surface area and impairs gas exchange.', '{"a": "Asthma is inflammation and spasm of the bronchi and bronchioles, not alveolar wall destruction.", "b": "Pleurisy is inflammation of the pleural membranes.", "d": "Pneumonia fills the alveoli with fluid from infection but does not destroy their walls."}'::jsonb, 'Emphysema is a chronic disorder in which alveolar walls are damaged and the respiratory surface decreases; smoking is the major cause.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('69446587-839c-558e-ba3c-0435d3775050', 'neet_ug', 'Botany', 'Biological Classification', 'Which of the following are most suitable indicator of SO₂ pollution in the environment ?', '[{"id": "a", "text": "Fungi"}, {"id": "b", "text": "Lichens"}, {"id": "c", "text": "Conifers"}, {"id": "d", "text": "Algae"}]'::jsonb, 'b', 'Lichens do not grow in SO₂-polluted air, so they are good indicators of SO₂ pollution.', 'Lichens are symbiotic associations of an alga and a fungus. They are very sensitive to sulphur dioxide and disappear from polluted areas, so their presence or absence shows how clean the air is.', '{"a": "Free-living fungi are not specifically sensitive to SO₂.", "c": "Conifers tolerate a wide range of conditions and are not standard SO₂ indicators.", "d": "Algae are used as indicators of water pollution, not SO₂."}'::jsonb, 'Lichens = phycobiont (alga) + mycobiont (fungus); they are good pollution indicators.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('7bb55b7f-ade9-5037-bb68-d52bf5f98205', 'neet_ug', 'Botany', 'Molecular Basis of Inheritance', 'Satellite DNA is important because it :', '[{"id": "a", "text": "Codes for enzymes needed for DNA replication"}, {"id": "b", "text": "Codes for proteins needed in cell cycle"}, {"id": "c", "text": "Shows high degree of polymorphism in population and also the same degree of polymorphism in an individual, which is heritable from parents to children"}, {"id": "d", "text": "Does not code for proteins and is same in all members of the population"}]'::jsonb, 'c', 'Satellite (repetitive) DNA is highly polymorphic between people yet inherited, which makes it the basis of DNA fingerprinting.', 'Satellite DNA consists of non-coding tandem repeats. The number of repeats varies greatly between individuals (high polymorphism) but is passed from parents to children. This makes it useful as a marker for DNA fingerprinting and paternity testing.', '{"a": "Satellite DNA is non-coding.", "b": "Satellite DNA does not code for any protein.", "d": "It is non-coding, but it varies between people rather than being the same in all of them."}'::jsonb, 'VNTRs (satellite DNA) are the basis of DNA fingerprinting (Alec Jeffreys).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('c9149ef0-64ad-5aae-8aa4-fc19be273fc6', 'neet_ug', 'Zoology', 'Evolution', 'Industrial melanism is an example of :', '[{"id": "a", "text": "Neo Lamarckism"}, {"id": "b", "text": "Neo Darwinism"}, {"id": "c", "text": "Natural selection"}, {"id": "d", "text": "Mutation"}]'::jsonb, 'c', 'The rise of dark peppered moths in sooty England is a classic case of natural selection.', 'After industrialisation, tree trunks were darkened by soot, so light moths were easily spotted by birds while dark moths survived and reproduced. The population shifted towards dark forms because the environment selected them, which is natural selection in action.', '{"a": "No inheritance of acquired characters is involved.", "b": "Neo-Darwinism is a broad synthetic theory; the observation itself is an example of natural selection.", "d": "The dark variant already existed; the change in its frequency was driven by selection, not new mutation."}'::jsonb, 'Biston betularia (peppered moth) is NCERT''s example of directional natural selection.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('ed40f0b6-1ea8-5d83-8c00-0b2970724489', 'neet_ug', 'Zoology', 'Biotechnology: Principles and Processes', 'The introduction of t-DNA into plants involves :', '[{"id": "a", "text": "Allowing the plant roots to stand in water"}, {"id": "b", "text": "Infection of the plant by Agrobacterium tumefaciens"}, {"id": "c", "text": "Altering the pH of the soil, then heat shocking the plants"}, {"id": "d", "text": "Exposing the plants to cold for a brief period"}]'::jsonb, 'b', 'T-DNA is transferred into plant cells when Agrobacterium tumefaciens infects the plant.', 'Agrobacterium tumefaciens carries the Ti plasmid. When it infects a dicot, a segment called T-DNA is transferred and integrated into the plant genome. Disarmed Ti plasmids use this natural process as a vector to deliver desired genes.', '{"a": "Standing roots in water does not transfer any DNA.", "c": "Heat shock with CaCl₂ is used to make bacterial cells competent, not to transform plants through soil.", "d": "Cold exposure (vernalisation) has nothing to do with gene transfer."}'::jsonb, 'Ti plasmid of A. tumefaciens is a natural genetic engineer of plants.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('d4ad38a3-1f88-5940-b40a-c1981cec79a6', 'neet_ug', 'Botany', 'Biological Classification', 'Pick up the wrong statement :', '[{"id": "a", "text": "Nuclear membrane is present in Monera"}, {"id": "b", "text": "Cell wall is absent in Animalia"}, {"id": "c", "text": "Protista have photosynthetic and heterotrophic modes of nutrition"}, {"id": "d", "text": "Some fungi are edible"}]'::jsonb, 'a', 'Monera are prokaryotes, so they have no nuclear membrane.', 'Kingdom Monera contains bacteria, which are prokaryotes with a nucleoid and no nuclear envelope. The other statements are true: animal cells have no cell wall, protists include both photosynthetic and heterotrophic forms, and mushrooms and morels are edible fungi.', '{"b": "True: animal cells lack a cell wall.", "c": "True: for example, Euglena can be both photosynthetic and heterotrophic.", "d": "True: Agaricus and morels are edible."}'::jsonb, 'Monera is the only prokaryotic kingdom in Whittaker''s five-kingdom system.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('b1eed4c1-f7c5-50f7-a311-2f5d621ca04c', 'neet_ug', 'Botany', 'Photosynthesis in Higher Plants', 'In photosynthesis, the light-independent reactions take place at :', '[{"id": "a", "text": "Stromal matrix"}, {"id": "b", "text": "Thylakoid lumen"}, {"id": "c", "text": "Photosystem - I"}, {"id": "d", "text": "Photosystem-II"}]'::jsonb, 'a', 'The Calvin cycle (dark reaction) runs in the chloroplast stroma.', 'Light reactions (photosystems, electron transport and photolysis) take place on the thylakoid membranes. The ATP and NADPH they produce are used by the enzymes of the Calvin cycle, including RuBisCO, which are located in the stroma.', '{"b": "The lumen collects protons for chemiosmosis; no carbon fixation happens there.", "c": "PS I belongs to the light reactions.", "d": "PS II belongs to the light reactions and carries out water splitting."}'::jsonb, 'Thylakoid = light reaction; stroma = Calvin cycle.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('e0a09bce-22cf-5127-8991-772672537c09', 'neet_ug', 'Zoology', 'Human Health and Disease', 'Which of the following immunoglobulins does constitute the largest percentage in human milk?', '[{"id": "a", "text": "IgG"}, {"id": "b", "text": "IgD"}, {"id": "c", "text": "IgM"}, {"id": "d", "text": "IgA"}]'::jsonb, 'd', 'Colostrum and breast milk are rich in IgA, which gives the infant passive immunity.', 'The yellowish colostrum secreted in early lactation contains abundant IgA antibodies, which protect the infant''s gut. This is a form of natural passive immunity.', '{"a": "IgG crosses the placenta and is not the main antibody of milk.", "b": "IgD is a membrane antibody on B cells and is present only in trace amounts.", "c": "IgM is the first antibody made in a primary response and is a minor part of milk."}'::jsonb, 'Colostrum = IgA (passive immunity); placenta = IgG.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('104f36a0-a4b8-5597-b165-11d32ea9a46e', 'neet_ug', 'Physics', 'Electromagnetic Waves', 'The energy of the em waves is of the order of 15 keV. To which part of the spectrum does it belong?', '[{"id": "a", "text": "γ-rays"}, {"id": "b", "text": "X-rays"}, {"id": "c", "text": "Infra-red rays"}, {"id": "d", "text": "Ultraviolet rays"}]'::jsonb, 'b', '15 keV corresponds to λ ≈ 0.8 Å, which lies in the X-ray region.', 'λ = hc/E = 12400 eV·Å / 15000 eV ≈ 0.83 Å, that is about 8 × 10⁻¹¹ m. X-rays span about 10⁻⁸ to 10⁻¹³ m with energies of roughly keV to tens of keV, so 15 keV is an X-ray photon.', '{"a": "γ-rays typically have energies of hundreds of keV to MeV (λ < 10⁻¹² m).", "c": "IR photons have energies below about 1.6 eV.", "d": "UV photons have energies of only a few eV to about 100 eV."}'::jsonb, 'λ(Å) ≈ 12400 / E(eV).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('6e33beb1-66e3-50e6-9309-a6cefb125e32', 'neet_ug', 'Physics', 'Electromagnetic Induction', 'An electron moves on a straight line path XY as shown. The abcd is a coil adjacent to the path of electron. What will be the direction of current, if any, induced in the coil ?', '[{"id": "a", "text": "No current induced"}, {"id": "b", "text": "abcd"}, {"id": "c", "text": "adcd"}, {"id": "d", "text": "The current will reverse its direction as the electron goes past the coil"}]'::jsonb, 'd', 'The flux through the coil rises as the electron approaches and falls as it recedes, so the induced current reverses.', 'The moving electron acts like a small current element, and its magnetic field through the coil depends on its distance. As it approaches, the flux through the coil increases, and as it moves away the flux decreases. By Lenz''s law the induced current flows one way during the approach and the opposite way afterwards.', '{"a": "The flux through the coil changes with time, so an emf is induced.", "b": "A single fixed direction ignores the change from increasing to decreasing flux.", "c": "Gives one fixed sense only, and ''adcd'' is not even a proper loop order."}'::jsonb, 'Lenz''s law: the induced current opposes the change in flux, so its direction flips when the flux changes from increasing to decreasing.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', '/pyq/ug/2015/138.webp'),
('c4f5e4a9-8d8a-5be8-a8c2-11f079a36fbb', 'neet_ug', 'Physics', 'Mechanical Properties of Solids', 'The Young''s modulus of steel is twice that of brass. Two wires of same length and of same area of cross section, one of steel and another of brass are suspended from the same roof. If we want the lower ends of the wires to be at the same level, then the weights added to the steel and brass wires must be in the ratio of :', '[{"id": "a", "text": "1 : 1"}, {"id": "b", "text": "1 : 2"}, {"id": "c", "text": "2 : 1"}, {"id": "d", "text": "4 : 1"}]'::jsonb, 'c', 'Equal extension needs W ∝ Y, so W_steel : W_brass = 2 : 1.', 'Extension Δl = WL/(AY). For equal L, A and Δl, W/Y must be the same for both wires, so W_s/W_b = Y_s/Y_b = 2. The ratio is 2 : 1.', '{"a": "Equal loads would stretch the brass wire twice as much.", "b": "Inverts the ratio; the stiffer wire needs the larger load.", "d": "Extension is linear in Y, not quadratic."}'::jsonb, 'Δl = FL/(AY): for equal elongation, the load is proportional to Y.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('45b893d1-3c62-5418-bc25-20006907489d', 'neet_ug', 'Physics', 'Waves', 'A source of sound S emitting waves of frequency 100 Hz and an observer O are located at some distance from each other. The source is moving with a speed of 19.4 ms⁻¹ at an angle of 60° with the source observer line as shown in the figure. The observer is at rest. The apparent frequency observed by the observer (velocity of sound in air 330 ms⁻¹) is :', '[{"id": "a", "text": "97 Hz"}, {"id": "b", "text": "100 Hz"}, {"id": "c", "text": "103 Hz"}, {"id": "d", "text": "106 Hz"}]'::jsonb, 'c', 'Only the component 19.4 cos 60° = 9.7 m/s towards O matters: f′ = 100 × 330/320.3 ≈ 103 Hz.', 'The source''s velocity component along the line towards the observer is 19.4 × cos 60° = 9.7 m/s. f′ = f·v/(v − v_s) = 100 × 330/(330 − 9.7) = 100 × 330/320.3 ≈ 103 Hz.', '{"a": "This would correspond to the source moving away.", "b": "Ignores the Doppler effect of the approaching component.", "d": "Uses a larger velocity component than 9.7 m/s."}'::jsonb, 'In the Doppler effect, use only the velocity component along the source–observer line.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', '/pyq/ug/2015/144.webp'),
('6eb706c9-6366-509e-bbdf-7379b1f99e56', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'An automobile moves on a road with a speed of 54 kmh⁻¹. The radius of its wheels is 0.45 m and the moment of inertia of the wheel about its axis of rotation is 3 kgm². If the vehicle is brought to rest in 15s, the magnitude of average torque transmitted by its brakes to wheel is :', '[{"id": "a", "text": "2.86 kg m²s⁻²"}, {"id": "b", "text": "6.66 kg m²s⁻²"}, {"id": "c", "text": "8.58 kg m²s⁻²"}, {"id": "d", "text": "10.86 kg m²s⁻²"}]'::jsonb, 'b', 'ω₀ = 15/0.45 = 33.3 rad/s, α = 33.3/15 = 2.22 rad/s², τ = Iα ≈ 6.66 N m.', 'v = 54 km/h = 15 m/s, so the wheel''s ω₀ = v/r = 15/0.45 ≈ 33.33 rad/s. Stopping in 15 s gives α = 33.33/15 ≈ 2.22 rad/s². Torque τ = Iα = 3 × 2.22 ≈ 6.66 kg m² s⁻².', '{"a": "Does not match Iω₀/t for these values.", "c": "Comes from a wrong angular velocity.", "d": "Overestimates α."}'::jsonb, 'For rolling without slipping ω = v/r; average torque = IΔω/Δt.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('30c18c58-2e53-5a0b-ba8e-99cba14e31d3', 'neet_ug', 'Physics', 'Moving Charges and Magnetism', 'A rectangular coil of length 0.12m and width 0.1m having 50 turns of wire is suspended vertically in a uniform magnetic field of strength 0.2 Weber/m². The coil carries a current of 2 A. If the plane of the coil is inclined at an angle of 30° with the direction of the field, the torque required to keep the coil in stable equilibrium will be :', '[{"id": "a", "text": "0.12 Nm"}, {"id": "b", "text": "0.15 Nm"}, {"id": "c", "text": "0.20 Nm"}, {"id": "d", "text": "0.24 Nm"}]'::jsonb, 'c', 'The normal makes 60° with B, so τ = NIAB sin 60° = 0.24 × 0.866 ≈ 0.20 N m.', 'If the coil''s plane makes 30° with B, its area vector makes 60° with B. τ = NIAB sin 60° = 50 × 2 × (0.12 × 0.1) × 0.2 × 0.866 = 0.24 × 0.866 ≈ 0.208 N m, which is about 0.20 N m.', '{"a": "Uses sin 30° for the angle, treating the plane angle as the angle between the normal and B.", "b": "Not obtained from any consistent angle.", "d": "This is the maximum torque NIAB, as if sin θ = 1."}'::jsonb, 'τ = NIAB sin θ, where θ is the angle between the coil''s normal and B.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('f638518a-70a5-58be-aa7c-4b822ba47d70', 'neet_ug', 'Physics', 'Electrostatic Potential and Capacitance', 'A parallel plate air capacitor has capacity ''C'' distance of separation between plates is ''d'' and potential difference ''V'' is applied between the plates force of attraction between the plates of the parallel plate air capacitor is :', '[{"id": "a", "text": "C²V²/2d²"}, {"id": "b", "text": "C²V²/2d"}, {"id": "c", "text": "CV²/2d"}, {"id": "d", "text": "CV²/d"}]'::jsonb, 'c', 'F = Q²/(2ε₀A) = (CV)²/(2Cd) = CV²/(2d).', 'Each plate feels the field of the other plate only, σ/(2ε₀), so F = Q·σ/(2ε₀) = Q²/(2ε₀A). With Q = CV and ε₀A = Cd, F = C²V²/(2Cd) = CV²/(2d). Equivalently, F = U/d with U = ½CV².', '{"a": "Dimensionally wrong for a force.", "b": "Forgets to replace ε₀A by Cd.", "d": "Uses the full field E = V/d instead of half of it."}'::jsonb, 'Force between capacitor plates = Q²/(2ε₀A) = ½ε₀E²A.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('b2d04191-f5ea-5b65-909f-9c79475206ab', 'neet_ug', 'Physics', 'Kinetic Theory', 'Two vessels separately contain two ideal gases A and B at the same temperature, the pressure of A being twice that of B. Under such conditions, the density of A is found to be 1.5 times the density of B. The ratio of molecular weight of A and B is :', '[{"id": "a", "text": "1/2"}, {"id": "b", "text": "2/3"}, {"id": "c", "text": "3/4"}, {"id": "d", "text": "2"}]'::jsonb, 'c', 'M = ρRT/P, so M_A/M_B = (ρ_A/ρ_B)(P_B/P_A) = 1.5 × ½ = 3/4.', 'For an ideal gas, P = ρRT/M, so M = ρRT/P. At the same T, M_A/M_B = (ρ_A/ρ_B) × (P_B/P_A) = 1.5 × (1/2) = 0.75 = 3/4.', '{"a": "Ignores the density ratio.", "b": "Inverts the density ratio.", "d": "Multiplies by the pressure ratio instead of dividing."}'::jsonb, 'PM = ρRT for an ideal gas.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('727b6c6c-1b5d-5cb0-92f4-61f928e830b6', 'neet_ug', 'Physics', 'Gravitation', 'A satellite S is moving in an elliptical orbit around the earth. The mass of the satellite is very small compared to the mass of the earth. Then,', '[{"id": "a", "text": "the acceleration of S is always directed towards the centre of the earth."}, {"id": "b", "text": "the angular momentum of S about the centre of the earth changes in direction, but its magnitude remains constant."}, {"id": "c", "text": "the total mechanical energy of S varies periodically with time."}, {"id": "d", "text": "the linear momentum of S remains constant in magnitude."}]'::jsonb, 'a', 'Gravity is the only force and points to Earth''s centre, so the satellite''s acceleration always does too.', 'The only force on the satellite is Earth''s gravity, which is central, so the acceleration always points to Earth''s centre. A central force exerts no torque about the centre, so angular momentum is constant in both magnitude and direction. Total energy is conserved, and the speed (and so momentum) changes around the elliptical orbit.', '{"b": "No torque acts, so even the direction of L is fixed.", "c": "Gravity is conservative, so total mechanical energy is constant.", "d": "Speed is greatest at perigee and least at apogee, so |p| varies."}'::jsonb, 'Central force ⇒ constant angular momentum ⇒ Kepler''s law of areas.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('79280425-b3b0-530a-9a1b-a4b7ed6ca1c8', 'neet_ug', 'Physics', 'Semiconductor Electronics: Materials, Devices and Simple Circuits', 'In the given figure, a diode D is connected to an external resistance R = 100 Ω and an e.m.f of 3.5V. If the barrier potential developed across the diode is 0.5 V, the current in the circuit will be :', '[{"id": "a", "text": "35 mA"}, {"id": "b", "text": "30 mA"}, {"id": "c", "text": "40 mA"}, {"id": "d", "text": "20 mA"}]'::jsonb, 'b', 'I = (3.5 − 0.5)/100 = 30 mA.', 'The diode is forward biased and drops its barrier potential of 0.5 V. The remaining 3.0 V falls across R, so I = 3.0/100 = 0.030 A = 30 mA.', '{"a": "Ignores the 0.5 V drop across the diode.", "c": "Adds the barrier potential instead of subtracting it.", "d": "Subtracts the barrier potential twice."}'::jsonb, 'A conducting diode drops roughly its barrier potential (0.3 V Ge, 0.7 V Si).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', '/pyq/ug/2015/150.webp'),
('46f0fc79-e54a-53e0-85d9-1a7874b597f0', 'neet_ug', 'Physics', 'Gravitation', 'A remote-sensing satellite of earth revolves in a circular orbit at a height of 0.25 × 10⁶ m above the surface of earth. If earth''s radius is 6.38 × 10⁶ m and g = 9.8 ms⁻², then the orbital speed of the satellite is :', '[{"id": "a", "text": "6.67 km s⁻¹"}, {"id": "b", "text": "7.76 km s⁻¹"}, {"id": "c", "text": "8.56 km s⁻¹"}, {"id": "d", "text": "9.13 km s⁻¹"}]'::jsonb, 'b', 'v = √(gR²/(R+h)) = √(9.8 × (6.38×10⁶)²/6.63×10⁶) ≈ 7.76 km/s.', 'v = √(GM/(R+h)) = √(gR²/(R+h)). R + h = 6.63 × 10⁶ m, so v² = 9.8 × 4.070 × 10¹³ / 6.63 × 10⁶ ≈ 6.02 × 10⁷ m²/s². This gives v ≈ 7.76 × 10³ m/s.', '{"a": "Too low for an orbit this close to the surface.", "c": "Higher than the speed for a grazing orbit (≈ 7.9 km/s), so impossible at this height.", "d": "Far above orbital speed at this height."}'::jsonb, 'Orbital speed near Earth''s surface is √(gR) ≈ 7.9 km/s, and it decreases with height.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('295436da-bce9-520e-9728-1d7a98191c94', 'neet_ug', 'Physics', 'Motion in a Plane', 'The position vector of a particle R⃗ as a function of time is given by :
R⃗ = 4sin(2πt) î + 4cos(2πt) ĵ
Where R is in meters, t is in seconds and î and ĵ denote unit vectors along x and y-directions, respectively. Which one of the following statements is wrong for the motion of particle ?', '[{"id": "a", "text": "Path of the particle is a circle of radius 4 meter"}, {"id": "b", "text": "Acceleration vectors is along −R⃗"}, {"id": "c", "text": "Magnitude of acceleration vector is v²/R where v is the velocity of particle."}, {"id": "d", "text": "Magnitude of the velocity of particle is 8 meter/second"}]'::jsonb, 'd', 'The speed is ωR = 2π × 4 = 8π m/s, not 8 m/s.', 'x² + y² = 16, so the path is a circle of radius 4 m traversed with ω = 2π rad/s. v⃗ = 8π cos(2πt) î − 8π sin(2πt) ĵ, so |v| = 8π m/s. The acceleration is −ω²R⃗, pointing towards the centre, with magnitude v²/R. Only statement (4) is wrong.', '{"a": "True: x² + y² = 16.", "b": "True: a⃗ = −4π²R⃗.", "c": "True: this is uniform circular motion, so the acceleration is v²/R."}'::jsonb, 'Uniform circular motion: v = ωR, a = ω²R = v²/R towards the centre.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('8e44f262-683c-5184-8e75-4b6f028222f8', 'neet_ug', 'Physics', 'Waves', 'A string is stretched between fixed points separated by 75.0 cm. It is observed to have resonant frequencies of 420 Hz and 315 Hz. There are no other resonant frequencies between these two. The lowest resonant frequencies for this string is :', '[{"id": "a", "text": "105 Hz"}, {"id": "b", "text": "155 Hz"}, {"id": "c", "text": "205 Hz"}, {"id": "d", "text": "10.5 Hz"}]'::jsonb, 'a', 'Consecutive harmonics differ by the fundamental: 420 − 315 = 105 Hz.', 'For a string fixed at both ends, fₙ = n·f₁, so adjacent resonances differ by f₁. Here f₁ = 420 − 315 = 105 Hz, and 315 = 3f₁ and 420 = 4f₁ confirm it.', '{"b": "315 and 420 are not integer multiples of 155.", "c": "Not a common divisor of 315 and 420 that fits consecutive harmonics.", "d": "With f₁ = 10.5 Hz there would be many resonances between 315 and 420 Hz."}'::jsonb, 'Fixed–fixed string: all harmonics present, fₙ = nv/2L.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('4b2efff0-b35c-5e55-93c3-9c2325fbdc76', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'Point masses m₁ and m₂ are placed at the opposite ends of a rigid rod of length L, and negligible mass. The rod is to be set rotating about an axis perpendicular to it. The position of point P on this rod through which the axis should pass so that the work required to set the rod rotating with angular velocity ω₀ is minimum, is given by :', '[{"id": "a", "text": "x = m₂L/(m₁ + m₂)"}, {"id": "b", "text": "x = m₁L/(m₁ + m₂)"}, {"id": "c", "text": "x = (m₁/m₂)L"}, {"id": "d", "text": "x = (m₂/m₁)L"}]'::jsonb, 'a', 'The work ½Iω₀² is least when I is least, which happens for an axis through the centre of mass: x = m₂L/(m₁+m₂).', 'I = m₁x² + m₂(L − x)². Setting dI/dx = 2m₁x − 2m₂(L − x) = 0 gives x = m₂L/(m₁ + m₂), measured from m₁. This is the centre of mass, where the moment of inertia is minimum, so the kinetic energy needed is minimum.', '{"b": "Swaps the masses; this point is not the centre of mass.", "c": "Not even dimensionally bounded by L, and not the centre of mass.", "d": "Same issue; it can exceed L."}'::jsonb, 'Among parallel axes, I is least about the axis through the centre of mass (parallel-axis theorem).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', '/pyq/ug/2015/154.webp'),
('c5735a83-76bc-5274-9dda-8b4a5ba857ae', 'neet_ug', 'Physics', 'Wave Optics', 'At the first minimum adjacent to the central maximum of a single-slit diffraction pattern the phase difference between the Huygen''s wavelet from the edge of the slit and the wavelet from the mid point of the slit is :', '[{"id": "a", "text": "π/8 radian"}, {"id": "b", "text": "π/4 radian"}, {"id": "c", "text": "π/2 radian"}, {"id": "d", "text": "π radian"}]'::jsonb, 'd', 'At the first minimum a sin θ = λ, so points a/2 apart differ in path by λ/2, a phase of π.', 'The first minimum occurs where a sin θ = λ. The edge and the midpoint are a/2 apart, so their path difference is (a/2) sin θ = λ/2, which corresponds to a phase difference of (2π/λ)(λ/2) = π. These pairs cancel, which is why the intensity is zero there.', '{"a": "Corresponds to a path difference of only λ/16.", "b": "Corresponds to λ/8.", "c": "Corresponds to λ/4; this would not give cancellation."}'::jsonb, 'Single slit first minimum: a sin θ = λ; split the slit into two halves that cancel pairwise.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('e7394707-2c19-5fac-99c2-248a4875464b', 'neet_ug', 'Physics', 'System of Particles and Rotational Motion', 'A force F⃗ = αî + 3ĵ + 6k̂ is acting at a point r⃗ = 2î − 6ĵ − 12k̂. The value of α for which angular momentum about origin is conserved is :', '[{"id": "a", "text": "1"}, {"id": "b", "text": "−1"}, {"id": "c", "text": "2"}, {"id": "d", "text": "zero"}]'::jsonb, 'b', 'Zero torque needs F⃗ ∥ r⃗; since r⃗ = −2(−î + 3ĵ + 6k̂), α = −1.', 'Angular momentum is conserved if τ⃗ = r⃗ × F⃗ = 0, i.e. F⃗ is parallel to r⃗. The ratios must match: α/2 = 3/(−6) = 6/(−12) = −½, so α = −1.', '{"a": "Gives α/2 = +½, which does not match −½.", "c": "The ratio α/2 = 1 is inconsistent.", "d": "With α = 0, r⃗ × F⃗ = (−36+36)î + (0−12)ĵ + (0−6)k̂ ≠ 0."}'::jsonb, 'L is conserved when the net torque is zero: r⃗ × F⃗ = 0 means F⃗ ∥ r⃗.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('84a153bc-ed29-5114-b030-176391882ac7', 'neet_ug', 'Physics', 'Motion in a Plane', 'Two particles A and B move with constant velocities v⃗₁ and v⃗₂. At the initial moment their position vectors are r⃗₁ and r⃗₂ respectively. The condition for particles A and B for their collision is:', '[{"id": "a", "text": "r⃗₁ − r⃗₂ = v⃗₁ − v⃗₂"}, {"id": "b", "text": "(r⃗₁ − r⃗₂)/|r⃗₁ − r⃗₂| = (v⃗₂ − v⃗₁)/|v⃗₂ − v⃗₁|"}, {"id": "c", "text": "r⃗₁·v⃗₁ = r⃗₂·v⃗₂"}, {"id": "d", "text": "r⃗₁ × v⃗₁ = r⃗₂ × v⃗₂"}]'::jsonb, 'b', 'They collide only if the relative velocity points exactly along the line joining them, toward the other particle.', 'Collision needs r⃗₁ + v⃗₁t = r⃗₂ + v⃗₂t for some t > 0, i.e. r⃗₁ − r⃗₂ = (v⃗₂ − v⃗₁)t. So the vector r⃗₁ − r⃗₂ must be a positive multiple of v⃗₂ − v⃗₁, meaning their unit vectors are equal.', '{"a": "Equates displacement with velocity difference (dimensionally inconsistent and true only at t = 1 with wrong sign).", "c": "Equal dot products have no bearing on meeting at a point.", "d": "Equal angular momenta about the origin do not ensure the paths meet at the same time."}'::jsonb, 'For two uniformly moving bodies, analyse in the frame of one: relative velocity must point along the relative position vector.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('68f4313c-ea5f-518c-8228-f28c9688921d', 'neet_ug', 'Physics', 'Current Electricity', 'Two metal wires of identical dimensions are connected in series. If σ₁ and σ₂ are the conductivities of the metal wires respectively, the effective conductivity of the combination is:', '[{"id": "a", "text": "σ₁σ₂/(σ₁ + σ₂)"}, {"id": "b", "text": "2σ₁σ₂/(σ₁ + σ₂)"}, {"id": "c", "text": "(σ₁ + σ₂)/(2σ₁σ₂)"}, {"id": "d", "text": "(σ₁ + σ₂)/(σ₁σ₂)"}]'::jsonb, 'b', 'Series resistances add, so the combined wire of length 2l has conductivity equal to the harmonic mean 2σ₁σ₂/(σ₁+σ₂).', 'Each wire: R = l/(σA). Series: R = l/(σ₁A) + l/(σ₂A). The combination has length 2l and area A, so 2l/(σA) = l/A(1/σ₁ + 1/σ₂), giving σ = 2σ₁σ₂/(σ₁ + σ₂).', '{"a": "Forgets that the combined length is 2l.", "c": "Reciprocal of the correct answer; has wrong dimensions.", "d": "Has dimensions of 1/σ."}'::jsonb, 'Resistance R = ρl/A = l/(σA); resistances in series add.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('26584806-ae9d-5949-9964-29dce76551e2', 'neet_ug', 'Physics', 'Kinetic Theory', '4.0 g of a gas occupies 22.4 litres at NTP. The specific heat capacity of the gas at constant volume is 5.0 J K⁻¹ mol⁻¹. If the speed of sound in this gas at NTP is 952 m s⁻¹, then the heat capacity at constant pressure is (Take gas constant R = 8.3 J K⁻¹ mol⁻¹)', '[{"id": "a", "text": "8.5 J K⁻¹ mol⁻¹"}, {"id": "b", "text": "8.0 J K⁻¹ mol⁻¹"}, {"id": "c", "text": "7.5 J K⁻¹ mol⁻¹"}, {"id": "d", "text": "7.0 J K⁻¹ mol⁻¹"}]'::jsonb, 'b', 'From v = √(γRT/M), γ = 1.6, so Cp = γCv = 8.0 J K⁻¹ mol⁻¹.', 'Molar mass M = 4.0 × 10⁻³ kg mol⁻¹. γ = Mv²/(RT) = (4×10⁻³ × 952²)/(8.3 × 273) = 3625/2266 ≈ 1.6. Cp = γCv = 1.6 × 5.0 = 8.0 J K⁻¹ mol⁻¹.', '{"a": "Does not match γ = 1.6.", "c": "Would need γ = 1.5.", "d": "Would need γ = 1.4."}'::jsonb, 'Speed of sound in a gas v = √(γRT/M); γ = Cp/Cv.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('bec5578c-8d31-5998-87f2-bb8e4d23a66e', 'neet_ug', 'Physics', 'Alternating Current', 'A series R-C circuit is connected to an alternating voltage source. Consider two situations:
(a) When capacitor is air filled.
(b) When capacitor is mica filled.
Current through resistor is i and voltage across capacitor is V, then:', '[{"id": "a", "text": "V_a = V_b"}, {"id": "b", "text": "V_a < V_b"}, {"id": "c", "text": "V_a > V_b"}, {"id": "d", "text": "i_a > i_b"}]'::jsonb, 'c', 'Mica raises C and lowers X_C, so the capacitor takes a smaller share of the source voltage: V_a > V_b.', 'V_C = V₀X_C/√(R² + X_C²) = V₀/√((R/X_C)² + 1), which increases with X_C. Mica (K > 1) increases C, so X_C = 1/(ωC) drops, V_C falls and current rises. Hence V_a > V_b and i_a < i_b.', '{"a": "Capacitance changes, so the voltage division changes.", "b": "Reversed: smaller X_C gives smaller capacitor voltage.", "d": "Impedance falls with mica, so i_b > i_a."}'::jsonb, 'A dielectric of constant K multiplies capacitance by K; X_C = 1/(ωC).', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('0d6b4a0c-8003-5382-a479-e4873aa88dc5', 'neet_ug', 'Physics', 'Laws of Motion', 'A plank with a box on it at one end is gradually raised about the other end. As the angle of inclination with the horizontal reaches 30°, the box starts to slip and slides 4.0 m down the plank in 4.0 s. The coefficients of static and kinetic friction between the box and the plank will be, respectively:', '[{"id": "a", "text": "0.4 and 0.3"}, {"id": "b", "text": "0.6 and 0.6"}, {"id": "c", "text": "0.6 and 0.5"}, {"id": "d", "text": "0.5 and 0.6"}]'::jsonb, 'c', 'μs = tan 30° ≈ 0.6, and the measured acceleration of 0.5 m s⁻² gives μk ≈ 0.5.', 'Slipping begins at the angle of repose: μs = tan 30° = 0.577 ≈ 0.6. From s = ½at² with u = 0: 4 = ½a(16), a = 0.5 m s⁻². a = g(sin 30° − μk cos 30°) gives 0.5 = 10(0.5 − 0.866μk), μk = 4.5/8.66 ≈ 0.52 ≈ 0.5.', '{"a": "μs does not equal tan 30°.", "b": "Box accelerates, so μk must be less than μs.", "d": "Kinetic friction cannot exceed static friction here."}'::jsonb, 'Angle of repose: tan θ = μs; kinetic friction is usually less than limiting static friction.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', '/pyq/ug/2015/163.webp'),
('a455966e-0bbf-55fb-8921-931d3785e87d', 'neet_ug', 'Physics', 'Laws of Motion', 'Two stones of masses m and 2m are whirled in horizontal circles, the heavier one in a radius r/2 and the lighter one in radius r. The tangential speed of lighter stone is n times that of the value of heavier stone when they experience same centripetal forces. The value of n is:', '[{"id": "a", "text": "1"}, {"id": "b", "text": "2"}, {"id": "c", "text": "3"}, {"id": "d", "text": "4"}]'::jsonb, 'b', 'Equal centripetal forces give 2mv²/(r/2) = m(nv)²/r, so n² = 4 and n = 2.', 'Heavier: F = 2m v²/(r/2) = 4mv²/r. Lighter: F = m(nv)²/r = n²mv²/r. Equating, n² = 4, n = 2.', '{"a": "Ignores the differences in mass and radius.", "c": "No consistent relation gives 3.", "d": "This is n², not n."}'::jsonb, 'Centripetal force F = mv²/r.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('646ff60d-f40a-586c-ab61-8c476cf5607d', 'neet_ug', 'Physics', 'Thermodynamics', 'The coefficient of performance of a refrigerator is 5. If the temperature inside freezer is −20 °C, the temperature of the surroundings to which it rejects heat is:', '[{"id": "a", "text": "21 °C"}, {"id": "b", "text": "31 °C"}, {"id": "c", "text": "41 °C"}, {"id": "d", "text": "11 °C"}]'::jsonb, 'b', 'With COP = T_L/(T_H − T_L) = 5 and T_L = 253 K, T_H ≈ 304 K ≈ 31 °C.', 'T_L = 253 K. 5 = 253/(T_H − 253) gives T_H − 253 = 50.6, T_H = 303.6 K ≈ 30.6 °C ≈ 31 °C.', '{"a": "Corresponds to a COP of about 6.", "c": "Corresponds to a COP of about 4.", "d": "Corresponds to a COP of about 8."}'::jsonb, 'Ideal refrigerator COP β = T_L/(T_H − T_L), temperatures in kelvin.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('cd67292e-ac7a-5122-9991-c0206f15aa6d', 'neet_ug', 'Physics', 'Thermodynamics', 'An ideal gas is compressed to half its initial volume by means of several processes. Which of the process results in the maximum work done on the gas?', '[{"id": "a", "text": "Isothermal"}, {"id": "b", "text": "Adiabatic"}, {"id": "c", "text": "Isobaric"}, {"id": "d", "text": "Isochoric"}]'::jsonb, 'b', 'In an adiabatic compression the pressure rises fastest, so the area under the p-V curve, and the work done on the gas, is largest.', 'Starting from the same state and going to V/2, the adiabatic curve (pVᵞ = const) lies above the isothermal (pV = const), which lies above the isobaric line. Work done on the gas is the area under the curve, so adiabatic > isothermal > isobaric. An isochoric process cannot change volume and does zero work.', '{"a": "Isothermal pressure rises less steeply than adiabatic, so less area.", "c": "Pressure stays at the initial value: least work among compressions.", "d": "No volume change, so no work."}'::jsonb, 'Adiabatic curves are γ times steeper than isotherms on a p-V diagram.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('d2c5aeb4-25bc-513f-ab2f-1d78c76c3415', 'neet_ug', 'Physics', 'Work, Energy and Power', 'A ball is thrown vertically downwards from a height of 20 m with an initial velocity v₀. It collides with the ground, loses 50 percent of its energy in collision and rebounds to the same height. The initial velocity v₀ is: (Take g = 10 m s⁻²)', '[{"id": "a", "text": "10 m s⁻¹"}, {"id": "b", "text": "14 m s⁻¹"}, {"id": "c", "text": "20 m s⁻¹"}, {"id": "d", "text": "28 m s⁻¹"}]'::jsonb, 'c', 'Energy after impact must be mg(20), so energy before impact is twice that, giving ½v₀² = 200 and v₀ = 20 m s⁻¹.', 'Per unit mass, rebounding to 20 m needs KE after impact = gh = 200 J kg⁻¹. Losing 50% means KE before impact = 400 J kg⁻¹. Energy conservation on the way down: ½v₀² + gh = 400, so ½v₀² = 200, v₀ = 20 m s⁻¹.', '{"a": "Gives total energy 250 J kg⁻¹, not 400.", "b": "Gives about 298 J kg⁻¹ before impact.", "d": "Gives about 592 J kg⁻¹ before impact."}'::jsonb, 'Mechanical energy is conserved in free fall: ½mv² + mgh = constant.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('ba5c4e33-2a7d-5d4c-b98c-d7130309e575', 'neet_ug', 'Physics', 'Work, Energy and Power', 'On a frictionless surface, a block of mass M moving at speed v collides elastically with another block of same mass M which is initially at rest. After collision the first block moves at an angle θ to its initial direction and has a speed v/3. The second block''s speed after the collision is:', '[{"id": "a", "text": "(√3/2)v"}, {"id": "b", "text": "(2√2/3)v"}, {"id": "c", "text": "(3/4)v"}, {"id": "d", "text": "(3/√2)v"}]'::jsonb, 'b', 'Kinetic energy conservation in the elastic collision gives v''² = v² − v²/9, so v'' = (2√2/3)v.', 'Elastic: ½Mv² = ½M(v/3)² + ½Mv''². So v''² = v²(1 − 1/9) = 8v²/9 and v'' = (2√2/3)v. (For equal masses the two final velocities are then at right angles.)', '{"a": "Gives KE total of 3/4 + 1/9 of the initial, not 1.", "c": "Does not conserve kinetic energy.", "d": "Exceeds the initial speed, violating energy conservation."}'::jsonb, 'In an elastic collision both momentum and kinetic energy are conserved.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('af36eda5-9d1d-55ad-8740-490431dbf3ad', 'neet_ug', 'Physics', 'Electrostatic Potential and Capacitance', 'If potential (in volts) in a region is expressed as V(x, y, z) = 6xy − y + 2yz, the electric field (in N/C) at point (1, 1, 0) is:', '[{"id": "a", "text": "−(6î + 9ĵ + k̂)"}, {"id": "b", "text": "−(3î + 5ĵ + 3k̂)"}, {"id": "c", "text": "−(6î + 5ĵ + 2k̂)"}, {"id": "d", "text": "−(2î + 3ĵ + k̂)"}]'::jsonb, 'c', 'E = −∇V = −[6y î + (6x − 1 + 2z) ĵ + 2y k̂], which at (1, 1, 0) is −(6î + 5ĵ + 2k̂).', '∂V/∂x = 6y = 6; ∂V/∂y = 6x − 1 + 2z = 5; ∂V/∂z = 2y = 2 at (1, 1, 0). So E = −(6î + 5ĵ + 2k̂) N/C.', '{"a": "Wrong y-component.", "b": "Partial derivatives evaluated incorrectly.", "d": "Partial derivatives evaluated incorrectly."}'::jsonb, 'Electric field is the negative gradient of potential: E = −∇V.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('bc0ea3fa-b86d-50da-8dfd-aa09be4956d4', 'neet_ug', 'Physics', 'Wave Optics', 'Two slits in Young''s experiment have widths in the ratio 1 : 25. The ratio of intensity at the maxima and minima in the interference pattern, I_max/I_min, is:', '[{"id": "a", "text": "4/9"}, {"id": "b", "text": "9/4"}, {"id": "c", "text": "121/49"}, {"id": "d", "text": "49/121"}]'::jsonb, 'b', 'Intensities are in ratio 1 : 25, amplitudes 1 : 5, so I_max/I_min = (5+1)²/(5−1)² = 9/4.', 'Intensity from each slit is proportional to its width: I₁ : I₂ = 1 : 25, so amplitudes a₁ : a₂ = 1 : 5. I_max/I_min = (a₁ + a₂)²/(a₂ − a₁)² = 36/16 = 9/4.', '{"a": "Inverted; the maximum must be brighter than the minimum.", "c": "Does not follow from amplitudes in the ratio 1 : 5.", "d": "Inverted and wrong values."}'::jsonb, 'I ∝ a²; I_max/I_min = (√I₁ + √I₂)²/(√I₁ − √I₂)².', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('8525ef68-645c-510b-918b-224685755ba3', 'neet_ug', 'Physics', 'Mechanical Properties of Fluids', 'The heart of a man pumps 5 litres of blood through the arteries per minute at a pressure of 150 mm of mercury. If the density of mercury be 13.6 × 10³ kg/m³ and g = 10 m/s², then the power of heart in watt is:', '[{"id": "a", "text": "1.50"}, {"id": "b", "text": "1.70"}, {"id": "c", "text": "2.35"}, {"id": "d", "text": "3.0"}]'::jsonb, 'b', 'Power = pressure × volume flow rate = (13.6×10³ × 10 × 0.15) × (5×10⁻³/60) ≈ 1.70 W.', 'P = ρgh = 13.6×10³ × 10 × 0.150 = 2.04 × 10⁴ Pa. Flow rate Q = 5×10⁻³ m³ / 60 s = 8.33 × 10⁻⁵ m³ s⁻¹. Power = PQ = 2.04×10⁴ × 8.33×10⁻⁵ ≈ 1.70 W.', '{"a": "Arithmetic error in P × Q.", "c": "Arithmetic error in P × Q.", "d": "Arithmetic error in P × Q."}'::jsonb, 'Power delivered by a pump = pressure × volume flow rate; pressure of a liquid column = hρg.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('e3e860ee-396c-53e2-b66f-a3bb983aaf19', 'neet_ug', 'Physics', 'Moving Charges and Magnetism', 'A proton and an alpha particle both enter a region of uniform magnetic field B, moving at right angles to the field B. If the radius of circular orbits for both the particles is equal and the kinetic energy acquired by proton is 1 MeV, the energy acquired by the alpha particle will be:', '[{"id": "a", "text": "1 MeV"}, {"id": "b", "text": "4 MeV"}, {"id": "c", "text": "0.5 MeV"}, {"id": "d", "text": "1.5 MeV"}]'::jsonb, 'a', 'With equal radii, K ∝ q²/m; the alpha has q² four times and m four times the proton''s, so K is the same, 1 MeV.', 'r = mv/(qB) = √(2mK)/(qB), so for equal r and B, K = q²B²r²/(2m) ∝ q²/m. For α: q = 2e, m = 4m_p, so q²/m = 4e²/(4m_p) = e²/m_p, the same as the proton. Hence K_α = 1 MeV.', '{"b": "Accounts only for the charge factor.", "c": "Treats K as proportional to q/m.", "d": "No consistent scaling gives 1.5."}'::jsonb, 'Radius of circular path in a magnetic field: r = mv/(qB) = √(2mK)/(qB).', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('44268a32-7e32-563d-a5cb-eb6138a43a0b', 'neet_ug', 'Physics', 'Units and Measurements', 'The dimensions of critical velocity v_c of liquid flowing through a tube are expressed as (ηˣ ρʸ rᶻ), where η, ρ and r are the coefficient of viscosity of liquid, density of liquid and radius of the tube respectively. Then the values of x, y and z are given by:', '[{"id": "a", "text": "1, 1, 1"}, {"id": "b", "text": "1, −1, −1"}, {"id": "c", "text": "−1, −1, 1"}, {"id": "d", "text": "−1, −1, −1"}]'::jsonb, 'b', 'Matching [LT⁻¹] with [ML⁻¹T⁻¹]ˣ[ML⁻³]ʸ[L]ᶻ gives x = 1, y = −1, z = −1, i.e. v_c ∝ η/(ρr).', '[LT⁻¹] = Mˣ⁺ʸ L⁻ˣ⁻³ʸ⁺ᶻ T⁻ˣ. T: −x = −1, x = 1. M: x + y = 0, y = −1. L: −1 + 3 + z = 1, z = −1. So v_c = kη/(ρr).', '{"a": "Mass dimension would not cancel.", "c": "Time exponent would be +1.", "d": "Time exponent would be +1."}'::jsonb, 'Critical velocity v_c = R_e η/(ρD), from the Reynolds number.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('fc1df7b1-34b3-596c-8465-9cc606a3aedb', 'neet_ug', 'Physics', 'Current Electricity', 'A circuit contains an ammeter, a battery of 30 V and a resistance 40.8 ohm all connected in series. If the ammeter has a coil of resistance 480 ohm and a shunt of 20 ohm, the reading in the ammeter will be:', '[{"id": "a", "text": "1 A"}, {"id": "b", "text": "0.5 A"}, {"id": "c", "text": "0.25 A"}, {"id": "d", "text": "2 A"}]'::jsonb, 'b', 'Ammeter resistance = 480 ∥ 20 = 19.2 Ω, total 60 Ω, so I = 30/60 = 0.5 A.', 'The shunted coil has resistance (480 × 20)/(480 + 20) = 19.2 Ω. Total resistance = 40.8 + 19.2 = 60 Ω. Current = 30/60 = 0.5 A, which is what the ammeter reads.', '{"a": "Uses only about 30 Ω total.", "c": "Uses 120 Ω total.", "d": "Uses 15 Ω total."}'::jsonb, 'An ammeter is a galvanometer with a low-resistance shunt in parallel: R_A = GS/(G + S).', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('62bde43d-b8a0-5b20-af76-d3dcbd6b9fd4', 'neet_ug', 'Physics', 'Mechanical Properties of Fluids', 'Water rises to height ''h'' in capillary tube. If the length of capillary tube above the surface of water is made less than ''h'', then:', '[{"id": "a", "text": "water does not rise at all."}, {"id": "b", "text": "water rises upto the tip of capillary tube and then starts overflowing like a fountain."}, {"id": "c", "text": "water rises upto the top of capillary tube and stays there without overflowing."}, {"id": "d", "text": "water rises upto a point a little below the top and stays there."}]'::jsonb, 'c', 'In a tube shorter than h, water reaches the top and the meniscus flattens (larger radius) so hR stays constant; it does not overflow.', 'Capillary rise h = 2T cos θ/(rρg), i.e. h × R (meniscus radius) is constant. When the tube length h'' < h, water climbs to the top and the meniscus radius increases to R'' = hR/h'', so the surface-tension force exactly supports the shorter column. No overflow occurs, since that would violate energy conservation.', '{"a": "Surface tension still pulls water up.", "b": "A perpetual fountain would violate energy conservation.", "d": "Water rises all the way to the rim, adjusting the meniscus curvature."}'::jsonb, 'Jurin''s law: h = 2T cos θ/(rρg); hr = constant for a given liquid.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('72b340b7-f9b7-50f0-b90e-c78ed14606f3', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'In an astronomical telescope in normal adjustment a straight black line of length L is drawn on inside part of objective lens. The eye-piece forms a real image of this line. The length of this image is l. The magnification of the telescope is:', '[{"id": "a", "text": "L/l"}, {"id": "b", "text": "L/l + 1"}, {"id": "c", "text": "L/l − 1"}, {"id": "d", "text": "(L + l)/(L − l)"}]'::jsonb, 'a', 'The eyepiece images the objective with magnification f_e/f_o, so l/L = f_e/f_o and M = f_o/f_e = L/l.', 'In normal adjustment the lenses are f_o + f_e apart. For the eyepiece, u = −(f_o + f_e); 1/v = 1/f_e − 1/(f_o + f_e) gives v = f_e(f_o + f_e)/f_o. Linear magnification = v/u (in size) = f_e/f_o = l/L. Hence M = f_o/f_e = L/l.', '{"b": "Adds a spurious 1 (as in the near-point simple microscope formula).", "c": "Subtracts a spurious 1.", "d": "Has no basis in the lens formula."}'::jsonb, 'Telescope in normal adjustment: M = f_o/f_e, tube length = f_o + f_e.', 'hard', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('2e82c515-1a8b-52da-93de-94c51358eff9', 'neet_ug', 'Physics', 'Thermal Properties of Matter', 'The value of coefficient of volume expansion of glycerin is 5 × 10⁻⁴ K⁻¹. The fractional change in the density of glycerin for a rise of 40 °C in its temperature, is:', '[{"id": "a", "text": "0.010"}, {"id": "b", "text": "0.015"}, {"id": "c", "text": "0.020"}, {"id": "d", "text": "0.025"}]'::jsonb, 'c', 'Density falls by a fraction ≈ γΔT = 5×10⁻⁴ × 40 = 0.020.', 'ρ'' = ρ/(1 + γΔT) ≈ ρ(1 − γΔT) for small γΔT. Fractional change |Δρ/ρ| ≈ γΔT = 5 × 10⁻⁴ × 40 = 0.020.', '{"a": "Uses half of γΔT.", "b": "Arithmetic error.", "d": "Arithmetic error."}'::jsonb, 'Volume expansion: ΔV/V = γΔT; density varies inversely with volume.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('0b63a2b2-0ebc-500c-8241-a7836484ce6d', 'neet_ug', 'Physics', 'Dual Nature of Radiation and Matter', 'A photoelectric surface is illuminated successively by monochromatic light of wavelength λ and λ/2. If the maximum kinetic energy of the emitted photoelectrons in the second case is 3 times that in the first case, the work function of the surface of the material is: (h = Planck''s constant, c = speed of light)', '[{"id": "a", "text": "hc/(3λ)"}, {"id": "b", "text": "hc/(2λ)"}, {"id": "c", "text": "hc/λ"}, {"id": "d", "text": "2hc/λ"}]'::jsonb, 'b', 'Setting 2hc/λ − φ = 3(hc/λ − φ) gives φ = hc/(2λ).', 'K₁ = hc/λ − φ and K₂ = 2hc/λ − φ. Given K₂ = 3K₁: 2hc/λ − φ = 3hc/λ − 3φ, so 2φ = hc/λ and φ = hc/(2λ).', '{"a": "Algebra slip in solving the equation.", "c": "Would make K₁ = 0, no emission in the first case.", "d": "Exceeds the first photon energy, so no emission at λ."}'::jsonb, 'Einstein''s photoelectric equation: K_max = hν − φ₀.', 'easy', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', NULL),
('189758fe-ad87-5847-a7f0-736350c4cf07', 'neet_ug', 'Physics', 'Ray Optics and Optical Instruments', 'A beam of light consisting of red, green and blue colours is incident on a right angled prism. The refractive index of the material of the prism for the above red, green and blue wavelengths are 1.39, 1.44 and 1.47, respectively. The prism will:', '[{"id": "a", "text": "separate the red colour part from the green and blue colours"}, {"id": "b", "text": "separate the blue colour part from the red and green colours"}, {"id": "c", "text": "separate all the three colours from one another"}, {"id": "d", "text": "not separate the three colours at all"}]'::jsonb, 'a', 'Light meets face AC at 45°; total internal reflection needs μ > √2 ≈ 1.414, so green and blue are reflected while red emerges.', 'Light enters face AB normally and strikes face AC at an incidence of 45°. TIR occurs if 45° > critical angle, i.e. μ > 1/sin 45° = 1.414. Green (1.44) and blue (1.47) are totally reflected; red (1.39) refracts out. So red is separated from green and blue.', '{"b": "Blue and green behave alike (both undergo TIR).", "c": "Green and blue both undergo TIR and stay together.", "d": "Red escapes, so a separation does occur."}'::jsonb, 'Critical angle: sin C = 1/μ; TIR when angle of incidence in the denser medium exceeds C.', 'med', true, 2015, NULL, 'NEET UG 2015 (NTA) · answer verified by UG Prep', '/pyq/ug/2015/180.webp')
ON CONFLICT (id) DO NOTHING;

